window.HAN_NICHI_N4_GRAMMAR_QUESTIONS=[{"id":"hn-grammar-26-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「どうしたんですか。」","options":["〜んです・〜のです","〜たらいい・〜といい","〜し、〜し","〜ないで"],"answer":0,"explanation":"〜んです・〜のです：Là vì...; thực ra là...; chuyện là...; dùng để giải thích hoặc nhấn mạnh 形：V普通形 + んです / Aい普通形 + んです / Na + な + んです / N + な + んです。「〜んです」 là dạng hội thoại phổ biến của 「〜のです」, dùng khi người nói muốn giải thích lý do, hoàn cảnh hoặc cung cấp thông tin nền cho một sự việc. Nó cũng được dùng khi người nói muốn hỏi lời giải thích về điều mình nhìn thấy hoặc nhận thấy, như 「どうしたんですか」. Trong câu hỏi, mẫu này thường thể hiện rằng người nói muốn biết nguyên nhân hoặc hoàn cảnh phía sau. Với tính từ な và danh từ ở hiện tại khẳng định phải dùng 「な」 trước 「んです」, như 「静かなんです」「学生なんです」. Không nên dịch máy móc 「んです」 thành một từ cố định; sắc thái thường là 'thực ra là...', 'chuyện là...', 'là vì...'.","sourceLesson":26,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-26","sourceRecordId":"grammar-26-1"},{"id":"hn-grammar-26-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「もう一度説明していただけませんか。」","options":["〜ていただけませんか","〜ている②","ずっと①","〜のに（用途）"],"answer":0,"explanation":"〜ていただけませんか：Anh/chị có thể vui lòng... được không?; có thể làm ơn... giúp tôi được không? 形：Vて + いただけませんか。「〜ていただけませんか」 là cách yêu cầu hoặc nhờ vả rất lịch sự, khiêm nhường, mang nghĩa 'anh/chị có thể vui lòng làm... giúp tôi được không?'. Đây là cách nói lịch sự hơn 「〜てください」 và 「〜てもらえませんか」. Người nói đặt mình ở vị trí nhận sự giúp đỡ, vì 「いただく」 là dạng khiêm nhường của 「もらう」. Mẫu này thích hợp khi nhờ giáo viên, cấp trên, khách hàng hoặc người không thân thiết làm điều gì đó.","sourceLesson":26,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-26","sourceRecordId":"grammar-26-2"},{"id":"hn-grammar-26-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「どこで切符を買ったらいいですか。」","options":["〜のが下手","〜ていた","〜つもりだ","〜たらいい・〜といい"],"answer":3,"explanation":"〜たらいい・〜といい：Nên...; sẽ tốt nếu...; giá mà...; hy vọng... 形：Vた + らいいです / V辞書形・Vない形 + といいです。「〜たらいい」 và 「〜といい」 đều có thể mang nghĩa 'sẽ tốt nếu...'. 「〜たらいい」 thường được dùng để đưa ra lời khuyên, đặc biệt trong mẫu 「どうしたらいいですか」 để hỏi 'nên làm thế nào?' và 「Vたらいいです」 để trả lời 'nên làm V'. 「〜といい」 thường dùng để diễn tả mong muốn hoặc hy vọng một sự việc xảy ra, như 「晴れるといいですね」 là 'hy vọng trời sẽ đẹp'. Vì vậy, tùy ngữ cảnh, hai mẫu có thể được dịch là 'nên...', 'sẽ tốt nếu...' hoặc 'hy vọng...'.","sourceLesson":26,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-26","sourceRecordId":"grammar-26-3"},{"id":"hn-grammar-27-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「わたしは日本語が話せます。」","options":["〜れる・〜られる（可能形）","N1にN2をいただく","〜ば〜ほど","〜ために"],"answer":0,"explanation":"〜れる・〜られる（可能形）：Có thể...; có khả năng làm... 形：五段動詞: 語尾をう段→え段 + る / 一段動詞: る→られる / する→できる / 来る→来られる。Thể khả năng（可能形）dùng để diễn tả năng lực hoặc điều kiện cho phép thực hiện một hành động, mang nghĩa 'có thể...'. Với động từ nhóm I (五段), đổi âm cuối từ hàng う sang hàng え rồi thêm 「る」, như 「書く→書ける」「話す→話せる」. Với động từ nhóm II (一段), bỏ 「る」 rồi thêm 「られる」, như 「食べる→食べられる」. 「する」 trở thành 「できる」 và 「来る」 trở thành 「来られる」. Trong câu khả năng, đối tượng của hành động thường được đánh dấu bằng 「が」 thay cho 「を」, như 「日本語が話せます」.","sourceLesson":27,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-27","sourceRecordId":"grammar-27-1"},{"id":"hn-grammar-27-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「窓から富士山が見えます。」","options":["Vれる・られる（受身形）","〜代わりに","すると","見える"],"answer":3,"explanation":"見える：Nhìn thấy; có thể nhìn thấy; hiện ra trong tầm mắt 形：N + が + 見えます。「見える」 diễn tả một vật tự nhiên nằm trong tầm nhìn và người nói có thể nhìn thấy nó mà không cần cố ý thực hiện hành động nhìn. Thường dùng mẫu 「Nが見えます」. Cần phân biệt với thể khả năng 「見られる」: 「見える」 là 'nhìn thấy được một cách tự nhiên/do nằm trong tầm mắt', còn 「見られる」 thường là 'có thể xem/nhìn' do có khả năng, cơ hội hoặc điều kiện cho phép.","sourceLesson":27,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-27","sourceRecordId":"grammar-27-2"},{"id":"hn-grammar-27-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「外から子どもの声が聞こえます。」","options":["聞こえる","お〜する","〜場合は","〜途中に・〜途中で"],"answer":0,"explanation":"聞こえる：Nghe thấy; có thể nghe thấy; vọng đến tai 形：N + が + 聞こえます。「聞こえる」 diễn tả âm thanh tự nhiên truyền đến tai và người nói nghe thấy nó mà không cần chủ động cố nghe, thường dùng mẫu 「Nが聞こえます」. Cần phân biệt với 「聞ける」: 「聞こえる」 là 'âm thanh tự lọt vào tai/nghe thấy được', còn 「聞ける」 là 'có thể nghe' do có cơ hội, phương tiện hoặc điều kiện để chủ động nghe.","sourceLesson":27,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-27","sourceRecordId":"grammar-27-3"},{"id":"hn-grammar-27-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「冷蔵庫に卵が一つしかありません。」","options":["〜しか〜ない","〜なら","ちゃんと・きちんと","お〜になる"],"answer":0,"explanation":"〜しか〜ない：Chỉ...; chỉ có...; ngoài... ra không có 形：N + しか + Vない / 数量 + しか + Vない。「〜しか〜ない」 dùng để nhấn mạnh sự giới hạn, mang nghĩa 'chỉ có...', 'chỉ làm...' hoặc 'ngoài... ra thì không...'. 「しか」 luôn đi với vị ngữ phủ định, nhưng toàn bộ câu thường được dịch sang tiếng Việt ở dạng khẳng định 'chỉ...'. Ví dụ 「100円しかありません」 nghĩa đen là 'ngoài 100 yên ra thì không có', tức 'chỉ có 100 yên'. So với 「だけ」 cũng có nghĩa 'chỉ', 「しか〜ない」 thường nhấn mạnh mạnh hơn cảm giác ít, thiếu hoặc giới hạn.","sourceLesson":27,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-27","sourceRecordId":"grammar-27-4"},{"id":"hn-grammar-28-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「音楽を聞きながら、勉強します。」","options":["V辞書形 + な","〜ている②","〜ながら","〜ために"],"answer":2,"explanation":"〜ながら：Vừa... vừa...; trong khi đang... 形：Vます → bỏ ます + ながら + V。「〜ながら」 dùng để diễn tả hai hành động được thực hiện đồng thời bởi cùng một chủ thể, mang nghĩa 'vừa A vừa B' hoặc 'trong khi A thì B'. Động từ đứng trước 「ながら」 bỏ 「ます」 rồi thêm 「ながら」, như 「聞きます→聞きながら」. Trong hai hành động, hành động đứng sau 「ながら」 thường là hành động chính, còn hành động đứng trước là hành động phụ diễn ra đồng thời.","sourceLesson":28,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-28","sourceRecordId":"grammar-28-1"},{"id":"hn-grammar-28-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「きのうの8時、テレビを見ていました。」","options":["〜ていた","〜のが下手","〜でできる・〜からできる","N1にN2をいただく"],"answer":0,"explanation":"〜ていた：Đã đang...; lúc đó đang...; đã từng thường xuyên... 形：Vて + いました / Vて + いた。「〜ていました」 là dạng quá khứ của 「〜ています」. Nó thường diễn tả một hành động đang diễn ra tại một thời điểm trong quá khứ, tương đương 'lúc đó đang...'. Ngoài ra, tùy loại động từ và ngữ cảnh, nó còn có thể diễn tả một trạng thái đã tồn tại hoặc một hành động được thực hiện lặp đi lặp lại trong một giai đoạn quá khứ. 「〜ていた」 là dạng thông thường, còn 「〜ていました」 là dạng lịch sự.","sourceLesson":28,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-28","sourceRecordId":"grammar-28-2"},{"id":"hn-grammar-28-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「この店は安いし、おいしいし、よく行きます。」","options":["〜ているところだ","では・それでは・じゃあ","〜し、〜し","〜なくて"],"answer":2,"explanation":"〜し、〜し：Vừa... vừa...; hơn nữa...; vì... và vì... 形：V普通形 + し / Aい普通形 + し / Na + だ + し / N + だ + し。「〜し、〜し」 dùng để liệt kê nhiều đặc điểm, sự việc hoặc lý do cùng loại. Khi dùng để nêu lý do, nó mang sắc thái 'vì A, hơn nữa còn vì B...'. Người nói có thể chỉ nêu một lý do với 「〜し」 để ngụ ý rằng vẫn còn những lý do khác. Trước 「し」 dùng dạng thông thường; với danh từ và tính từ な ở hiện tại khẳng định dùng 「だし」. Mẫu này thường xuất hiện cùng 「それに」 khi bổ sung thêm một lý do.","sourceLesson":28,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-28","sourceRecordId":"grammar-28-3"},{"id":"hn-grammar-28-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「このレストランは安いです。それに、おいしいです。」","options":["〜のは・〜のが","それに","〜るところだ","さ（感動詞）"],"answer":1,"explanation":"それに：Hơn nữa; thêm vào đó; vả lại; ngoài ra 形：文1。それに、文2。。「それに」 là liên từ dùng để bổ sung thêm một thông tin, đặc điểm hoặc lý do cùng hướng với nội dung đã nói trước đó, mang nghĩa 'hơn nữa, thêm vào đó, vả lại'. Trong bài này, 「それに」 thường được dùng cùng cấu trúc 「〜し」 để thêm một lý do hoặc ưu điểm/nhược điểm khác. Khác với 「でも」 mang ý đối lập, 「それに」 bổ sung thêm ý cùng chiều.","sourceLesson":28,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-28","sourceRecordId":"grammar-28-4"},{"id":"hn-grammar-28-5","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「電車が止まりました。それで、会社に遅れました。」","options":["〜たところだ","それで","〜てくる","あと・あとのN"],"answer":1,"explanation":"それで：Vì thế; do đó; bởi vậy; rồi sao? 形：文1（原因・理由）。それで、文2（結果）。。「それで」 là liên từ nối nguyên nhân với kết quả, mang nghĩa 'vì thế, do đó, bởi vậy'. Câu phía trước nêu nguyên nhân hoặc hoàn cảnh, còn câu phía sau nêu kết quả phát sinh một cách tự nhiên từ nguyên nhân đó. Trong hội thoại, 「それで？」 còn có thể dùng riêng với nghĩa 'rồi sao?', 'sau đó thế nào?' để yêu cầu người nói tiếp tục câu chuyện. Cần phân biệt với 「それに」: 「それに」 bổ sung thêm thông tin cùng chiều, còn 「それで」 chỉ kết quả do nội dung phía trước gây ra.","sourceLesson":28,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-28","sourceRecordId":"grammar-28-5"},{"id":"hn-grammar-29-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「窓が開いています。」","options":["〜ている②","〜ないで","NにV","〜のが下手"],"answer":0,"explanation":"〜ている②：Đang ở trạng thái...; đã... và kết quả vẫn còn 形：自動詞Vて + います。「〜ています」 trong bài này chủ yếu dùng với tự động từ để diễn tả trạng thái hiện tại là kết quả của một sự thay đổi đã xảy ra. Hành động hoặc sự thay đổi đã hoàn thành, nhưng kết quả của nó vẫn còn ở thời điểm nói. Ví dụ 「窓が開いています」 không có nghĩa là 'cửa sổ đang thực hiện hành động mở', mà là 'cửa sổ đang mở' — tức nó đã được mở và hiện vẫn ở trạng thái mở. Mẫu này thường gặp với các tự động từ như 「開く」「閉まる」「壊れる」「割れる」「消える」「汚れる」「落ちる」. Cần phân biệt với 「〜ている①」 chỉ hành động đang diễn ra như 「本を読んでいます」.","sourceLesson":29,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-29","sourceRecordId":"grammar-29-1"},{"id":"hn-grammar-29-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「宿題はもう全部してしまいました。」","options":["〜ために","〜かどうか","〜がする","〜てしまう・〜ちゃう"],"answer":3,"explanation":"〜てしまう・〜ちゃう：Làm xong hoàn toàn...; lỡ/trót...; đáng tiếc là... 形：Vて + しまいます / Vで + しまいます / 会話形: Vてしまう → Vちゃう・Vでしまう → Vじゃう。「〜てしまう」 có hai cách dùng chính. Thứ nhất, nó diễn tả một hành động được hoàn thành hoàn toàn hoặc làm xong hết, như 「宿題をしてしまいました」 là 'đã làm xong hết bài tập'. Thứ hai, nó diễn tả một việc ngoài ý muốn, sai sót hoặc kết quả đáng tiếc, thường mang sắc thái 'lỡ, trót, mất rồi', như 「財布をなくしてしまいました」 là 'tôi lỡ làm mất ví rồi'. Trong hội thoại thân mật, 「〜てしまう」 thường rút gọn thành 「〜ちゃう」 và 「〜でしまう」 thành 「〜じゃう」. Ở quá khứ, dùng 「〜ちゃった」「〜じゃった」.","sourceLesson":29,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-29","sourceRecordId":"grammar-29-2"},{"id":"hn-grammar-30-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「机の上に資料が置いてあります。」","options":["それに","〜てある","〜ずつ","〜と"],"answer":1,"explanation":"〜てある：Đã được làm sẵn; đang ở trạng thái đã được... 形：他動詞Vて + あります。「〜てあります」 dùng để diễn tả trạng thái hiện tại là kết quả của một hành động có chủ ý mà ai đó đã thực hiện trước đó. Thường hàm ý rằng hành động được làm vì một mục đích hoặc để chuẩn bị cho việc gì đó. Mẫu này chủ yếu dùng với tha động từ. Đối tượng vốn đi với 「を」 thường được đánh dấu bằng 「が」 khi nhấn mạnh trạng thái kết quả, như 「窓を開けます→窓が開けてあります」. Cần phân biệt với 「〜ています」 của tự động từ: 「窓が開いています」 chỉ trạng thái cửa sổ đang mở, còn 「窓が開けてあります」 hàm ý có người đã chủ động mở và để nó ở trạng thái đó.","sourceLesson":30,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-30","sourceRecordId":"grammar-30-1"},{"id":"hn-grammar-30-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「旅行の前に、ホテルを予約しておきます。」","options":["まだ","〜ておく","〜ば〜ほど","〜そう"],"answer":1,"explanation":"〜ておく：Làm trước...; chuẩn bị sẵn...; cứ để nguyên... 形：Vて + おきます。「〜ておきます」 thường dùng khi thực hiện một hành động trước để chuẩn bị cho một việc sẽ xảy ra sau đó, mang nghĩa 'làm trước, chuẩn bị sẵn'. Ngoài ra, nó còn có thể diễn tả việc duy trì nguyên trạng thái vì có lý do hoặc vì sau này sẽ cần, như 「そのままにしておきます」 là 'cứ để nguyên như vậy'. Trong hội thoại, 「〜ておく」 thường được rút gọn thành 「〜とく」, và 「〜でおく」 thành 「〜どく」.","sourceLesson":30,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-30","sourceRecordId":"grammar-30-2"},{"id":"hn-grammar-30-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「まだ雨が降っています。」","options":["〜によると・〜によれば","〜すぎる","まだ","A + さ"],"answer":2,"explanation":"まだ：Vẫn; vẫn còn; vẫn chưa... 形：まだ + 肯定形 / まだ + Vていません。「まだ」 diễn tả một trạng thái hoặc hành động vẫn tiếp tục tại thời điểm nói, mang nghĩa 'vẫn, vẫn còn'. Khi đi với câu phủ định, đặc biệt là 「まだ〜ていません」, nó mang nghĩa 'vẫn chưa...'. Ví dụ 「まだ雨が降っています」 là 'trời vẫn đang mưa', còn 「まだ食べていません」 là 'vẫn chưa ăn'. Cần phân biệt với 「もう」: 「もう」 thường diễn tả 'đã, rồi', trong khi 「まだ」 nhấn mạnh trạng thái vẫn tiếp tục hoặc một việc chưa xảy ra.","sourceLesson":30,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-30","sourceRecordId":"grammar-30-3"},{"id":"hn-grammar-30-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「ドアを開けました。すると、猫が入ってきました。」","options":["それに","〜か〜","すると","〜ばいい"],"answer":2,"explanation":"すると：Sau đó thì...; thế là...; ngay lúc đó...; nếu vậy thì... 形：文1。すると、文2。。「すると」 là liên từ dùng khi sau một hành động hoặc sự việc ở câu trước, một sự việc khác xảy ra ngay sau đó hoặc được phát hiện, mang nghĩa 'sau đó thì, thế là, ngay lúc đó'. Chủ thể của sự việc phía sau thường không nằm trong ý chí hoặc kế hoạch trực tiếp của người nói. Nó thường được dùng khi kể chuyện để diễn tả một diễn biến hoặc kết quả bất ngờ. Ngoài ra, trong hội thoại 「すると」 cũng có thể mang nghĩa 'nếu vậy thì, như vậy thì...' khi người nói suy ra điều gì đó từ thông tin vừa nghe.","sourceLesson":30,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-30","sourceRecordId":"grammar-30-4"},{"id":"hn-grammar-31-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「いっしょに昼ごはんを食べよう。」","options":["Vよう（意向形）","お〜願う","〜やすい","見える"],"answer":0,"explanation":"Vよう（意向形）：Hãy cùng...; ... nhé; tôi sẽ... 形：五段動詞: う段→お段 + う / 一段動詞: る→よう / する→しよう / 来る→来よう。意向形（thể ý chí）dùng để diễn tả ý định của người nói hoặc rủ người khác cùng thực hiện một hành động. Đây là dạng thông thường của 「〜ましょう」. Với động từ nhóm I, đổi âm cuối từ hàng う sang hàng お rồi thêm 「う」, như 「行く→行こう」「飲む→飲もう」. Với động từ nhóm II, bỏ 「る」 rồi thêm 「よう」, như 「食べる→食べよう」. 「する」 thành 「しよう」 và 「来る」 thành 「来よう」. Khi dùng một mình, nó có thể mang nghĩa 'hãy cùng... nhé' hoặc thể hiện quyết tâm 'mình sẽ...'. Thể này cũng được dùng trước 「と思っています」 để diễn tả một dự định.","sourceLesson":31,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-31","sourceRecordId":"grammar-31-1"},{"id":"hn-grammar-31-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「来年、日本へ留学するつもりです。」","options":["いたす","Vれる・られる（受身形）","Vよう（意向形）","〜つもりだ"],"answer":3,"explanation":"〜つもりだ：Dự định...; định sẽ...; có ý định... 形：V辞書形 + つもりです / Vない形 + つもりです。「〜つもりです」 dùng để diễn tả ý định hoặc quyết định tương đối rõ ràng của chính người nói về một hành động trong tương lai, mang nghĩa 'dự định, định sẽ...'. Với ý định không làm một việc, dùng 「Vない＋つもりです」. Mẫu này tập trung vào ý chí và quyết định cá nhân của người nói. So với 「予定です」, 「つもりです」 thiên về ý định chủ quan, còn 「予定です」 thiên về kế hoạch hoặc lịch trình đã được sắp xếp.","sourceLesson":31,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-31","sourceRecordId":"grammar-31-2"},{"id":"hn-grammar-31-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「来月、大阪へ出張する予定です。」","options":["〜中","〜予定だ","〜たばかり","V辞書形 + な"],"answer":1,"explanation":"〜予定だ：Có kế hoạch...; dự kiến...; theo lịch sẽ... 形：V辞書形 + 予定です / Vない形 + 予定です / Nの + 予定です。「〜予定です」 dùng để nói về một kế hoạch, lịch trình hoặc sự kiện đã được dự kiến, sắp xếp trước, mang nghĩa 'có kế hoạch..., dự kiến..., theo lịch sẽ...'. Có thể dùng với kế hoạch cá nhân cũng như lịch trình của công ty, trường học, phương tiện giao thông hoặc sự kiện. Khác với 「つもりです」 nhấn mạnh ý định của người nói, 「予定です」 nhấn mạnh kế hoạch hoặc lịch trình cụ thể đã được xác định.","sourceLesson":31,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-31","sourceRecordId":"grammar-31-3"},{"id":"hn-grammar-31-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「昼ごはんはまだ食べていません。」","options":["すると","まだ〜ていません","いたす","NにV"],"answer":1,"explanation":"まだ〜ていません：Vẫn chưa...; chưa làm... tính đến hiện tại 形：まだ + Vて + いません。Mẫu 「まだ〜ていません」 dùng để diễn tả một hành động được dự kiến hoặc có khả năng xảy ra nhưng tính đến thời điểm hiện tại vẫn chưa được thực hiện hoặc hoàn thành, mang nghĩa 'vẫn chưa...'. 「まだ」 nhấn mạnh rằng trạng thái chưa hoàn thành vẫn tiếp tục đến hiện tại. Cần phân biệt với quá khứ phủ định đơn thuần 「Vませんでした」: 「Vませんでした」 chỉ nói rằng một hành động đã không xảy ra trong quá khứ, còn 「まだVていません」 hàm ý rằng đến bây giờ vẫn chưa làm và hành động đó vẫn có thể xảy ra sau này.","sourceLesson":31,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-31","sourceRecordId":"grammar-31-4"},{"id":"hn-grammar-31-5","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「朝からずっと雨が降っています。」","options":["〜ないで","ずっと①","〜と","お〜になる"],"answer":1,"explanation":"ずっと①：Suốt; liên tục; mãi; từ... đến nay; suốt cả khoảng thời gian 形：ずっと + Vています / 時点・期間 + から + ずっと + Vています。「ずっと」 trong cách dùng này diễn tả một hành động hoặc trạng thái tiếp tục không ngừng trong một khoảng thời gian dài, mang nghĩa 'suốt, liên tục, mãi, suốt từ... đến nay'. Nó thường đi với 「〜ています」 khi trạng thái bắt đầu trong quá khứ và vẫn tiếp tục ở hiện tại. Có thể dùng cùng 「から」 để chỉ rõ điểm bắt đầu, như 「朝からずっと」 là 'suốt từ sáng đến giờ'. Ngoài cách dùng chỉ thời gian này, 「ずっと」 còn có cách dùng khác để nhấn mạnh mức độ so sánh, nhưng đó không phải trọng tâm của mẫu này.","sourceLesson":31,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-31","sourceRecordId":"grammar-31-5"},{"id":"hn-grammar-32-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「熱がありますから、病院へ行ったほうがいいです。」","options":["〜たほうがいい","聞こえる","N1にN2をいただく","〜れる・〜られる（可能形）"],"answer":0,"explanation":"〜たほうがいい：Nên...; tốt hơn là nên... 形：Vた + ほうがいいです。「〜たほうがいいです」 dùng để đưa ra lời khuyên hoặc đề nghị rằng thực hiện một hành động sẽ tốt hơn, mang nghĩa 'nên...' hoặc 'tốt hơn là nên...'. Động từ đứng trước 「ほうがいい」 dùng thể た. Mẫu này thường được dùng khi người nói cho rằng hành động đó có lợi cho người nghe dựa trên tình trạng hoặc hoàn cảnh hiện tại.","sourceLesson":32,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-32","sourceRecordId":"grammar-32-1"},{"id":"hn-grammar-32-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「熱がありますから、お風呂に入らないほうがいいです。」","options":["〜やすい","〜ないほうがいい","Vれる・られる（受身形）","〜ようになる"],"answer":1,"explanation":"〜ないほうがいい：Không nên...; tốt hơn là đừng... 形：Vない + ほうがいいです。「〜ないほうがいいです」 dùng để khuyên người khác không nên thực hiện một hành động vì hành động đó có thể gây ra kết quả không tốt. Mẫu này mang nghĩa 'không nên...' hoặc 'tốt hơn là đừng...'. Khác với 「〜てはいけません」 mang tính cấm đoán, 「〜ないほうがいい」 chỉ là lời khuyên dựa trên đánh giá của người nói.","sourceLesson":32,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-32","sourceRecordId":"grammar-32-2"},{"id":"hn-grammar-32-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「明日は雨が降るでしょう。」","options":["〜のに（逆接）","〜でしょう","N1がN2にN3をくださる","〜とおり"],"answer":1,"explanation":"〜でしょう：Chắc là...; có lẽ...; ... phải không? 形：V普通形 + でしょう / Aい普通形 + でしょう / Na + でしょう / N + でしょう。「〜でしょう」 trong bài này chủ yếu dùng để diễn tả sự suy đoán của người nói dựa trên thông tin hoặc tình hình hiện tại, mang nghĩa 'chắc là, có lẽ...'. Mức độ chắc chắn thường cao hơn 「〜かもしれません」. Với danh từ và tính từ な ở hiện tại khẳng định, không dùng 「だ」 trước 「でしょう」. Khi lên giọng ở cuối câu, 「でしょう？」 cũng có thể dùng để xác nhận thông tin với người nghe, mang nghĩa '... phải không?'.","sourceLesson":32,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-32","sourceRecordId":"grammar-32-3"},{"id":"hn-grammar-32-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「午後から雨が降るかもしれません。」","options":["〜やすい","〜かもしれない","〜代わりに","あと・あとのN"],"answer":1,"explanation":"〜かもしれない：Có lẽ...; có thể...; biết đâu... 形：V普通形 + かもしれません / Aい普通形 + かもしれません / Na + かもしれません / N + かもしれません。「〜かもしれません」 dùng khi người nói cho rằng một sự việc có khả năng xảy ra nhưng không chắc chắn, mang nghĩa 'có lẽ, có thể, biết đâu...'. Mức độ chắc chắn thường thấp hơn 「〜でしょう」. Với danh từ và tính từ な ở hiện tại khẳng định, bỏ 「だ」 trước 「かもしれません」, như 「雨かもしれません」「暇かもしれません」. 「かもしれない」 là dạng thông thường của 「かもしれません」.","sourceLesson":32,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-32","sourceRecordId":"grammar-32-4"},{"id":"hn-grammar-32-5","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「もしかしたら、明日は雪が降るかもしれません。」","options":["〜あとで","もしかしたら","〜ている②","〜んです・〜のです"],"answer":1,"explanation":"もしかしたら：Có lẽ; có thể; biết đâu; có khả năng 形：もしかしたら + 文 + かもしれません。「もしかしたら」 là phó từ dùng để nhấn mạnh rằng người nói đang đưa ra một khả năng không chắc chắn, mang nghĩa 'có lẽ, biết đâu, có thể'. Nó rất thường được dùng cùng 「〜かもしれません」. 「もしかしたら」 được đặt ở đầu hoặc trước nội dung được phỏng đoán, còn 「かもしれません」 đứng ở cuối mệnh đề.","sourceLesson":32,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-32","sourceRecordId":"grammar-32-5"},{"id":"hn-grammar-32-6","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「ここに入るな。」","options":["〜ので","〜でできる・〜からできる","V辞書形 + な","〜てみる"],"answer":2,"explanation":"V辞書形 + な：Đừng...; cấm...; không được... 形：V辞書形 + な。「V辞書形＋な」 là dạng cấm đoán trực tiếp, mạnh, mang nghĩa 'đừng...' hoặc 'cấm...'. Dạng này thường xuất hiện trên biển báo, khẩu lệnh, lời cảnh báo hoặc trong cách nói thân mật khi người nói có vị thế phù hợp. Vì sắc thái rất mạnh nên không nên dùng tùy tiện với người lớn tuổi, cấp trên hoặc người không thân. Cần phân biệt với 「〜ないでください」 là cách yêu cầu 'xin đừng...' lịch sự hơn.","sourceLesson":32,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-32","sourceRecordId":"grammar-32-6"},{"id":"hn-grammar-32-7","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「試験まであと一週間です。」","options":["〜つもりだ","あと・あとのN","〜によると・〜によれば","〜たところだ"],"answer":1,"explanation":"あと・あとのN：Phần còn lại; còn...; số còn lại; ... còn lại 形：あと + 数量 / あと + N / あとの + N。「あと」 trong cách dùng này diễn tả phần, số lượng hoặc thời gian còn lại sau khi một phần đã được sử dụng hoặc hoàn thành, mang nghĩa 'còn..., phần còn lại'. Ví dụ 「あと10分」 là 'còn 10 phút', 「あと一人」 là 'còn một người nữa'. Khi bổ nghĩa trực tiếp cho danh từ với nghĩa '... còn lại', có thể dùng 「あとの＋N」. Cần phân biệt với 「Vたあとで」 mang nghĩa 'sau khi làm...'.","sourceLesson":32,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-32","sourceRecordId":"grammar-32-7"},{"id":"hn-grammar-33-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「ここに入るな。」","options":["〜なら","V辞書形 + な","〜ないほうがいい","いらっしゃる"],"answer":1,"explanation":"V辞書形 + な：Đừng...; không được...; cấm... 形：V辞書形 + な。「V辞書形＋な」 là dạng cấm đoán trực tiếp, dùng để yêu cầu hoặc ra lệnh cho người khác không thực hiện một hành động, mang nghĩa 'đừng...' hoặc 'cấm...'. Đây là cách nói khá mạnh, thường xuất hiện trong mệnh lệnh, biển báo, cảnh báo, khẩu hiệu hoặc giữa những người có quan hệ thân mật khi hoàn cảnh cho phép. Ví dụ 「入るな」 là 'đừng vào'. Trong giao tiếp lịch sự, thường dùng 「〜ないでください」 thay vì dạng này.","sourceLesson":33,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-33","sourceRecordId":"grammar-33-1"},{"id":"hn-grammar-33-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「あと10分で授業が終わります。」","options":["〜ばいい","あと・あとのN","〜か〜","〜たほうがいい"],"answer":1,"explanation":"あと・あとのN：Còn lại; phần còn lại; thêm... nữa 形：あと + 数量 / あと + N / あとの + N。「あと」 trong cách dùng này chỉ phần, số lượng, thời gian hoặc công việc còn lại, mang nghĩa 'còn..., thêm... nữa, phần còn lại'. Ví dụ 「あと5分」 là 'còn 5 phút', 「あと一人」 là 'còn một người nữa'. Khi bổ nghĩa cho danh từ, 「あとの＋N」 có thể mang nghĩa 'N còn lại'. Cần phân biệt với 「Vたあとで」 hoặc 「Nのあとで」 mang nghĩa 'sau khi...'.","sourceLesson":33,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-33","sourceRecordId":"grammar-33-2"},{"id":"hn-grammar-34-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「土曜日か日曜日に買い物に行きます。」","options":["〜か〜","〜はずだ","N1にN2をいただく","〜やすい"],"answer":0,"explanation":"〜か〜：Hoặc...; hay...; A hoặc B 形：N1 + か + N2 / 文1 + か + 文2。「か」 dùng để nối hai hoặc nhiều lựa chọn, mang nghĩa 'hoặc, hay'. Khác với 「と」 dùng để liệt kê các đối tượng cùng tồn tại, 「か」 thể hiện sự lựa chọn giữa các phương án. Ví dụ 「土曜日か日曜日」 nghĩa là 'thứ bảy hoặc chủ nhật'. 「か」 cũng có thể xuất hiện giữa các lựa chọn là hành động hoặc nội dung câu, tùy ngữ cảnh.","sourceLesson":34,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-34","sourceRecordId":"grammar-34-1"},{"id":"hn-grammar-34-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「先生が言ったとおりに、書いてください。」","options":["〜てある","Vれる・られる（受身形）","Vてくださいませんか","〜とおり"],"answer":3,"explanation":"〜とおり：Theo đúng...; giống như...; đúng như... 形：V辞書形 + とおりに / Vた形 + とおりに / Nの + とおりに。「〜とおりに」 dùng để diễn tả việc thực hiện một hành động đúng theo một cách thức, hướng dẫn, mẫu hoặc nội dung nào đó, mang nghĩa 'theo đúng..., giống như..., đúng như...'. Với động từ có thể dùng 「V辞書形＋とおりに」 hoặc 「Vた＋とおりに」. Với danh từ dùng 「Nのとおりに」. 「とおり」 nhấn mạnh việc hành động hoặc kết quả phù hợp với điều được lấy làm mẫu.","sourceLesson":34,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-34","sourceRecordId":"grammar-34-2"},{"id":"hn-grammar-34-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「仕事が終わったあとで、友達と食事します。」","options":["〜しか〜ない","いらっしゃる","〜と","〜あとで"],"answer":3,"explanation":"〜あとで：Sau khi...; sau...; lát nữa 形：Vた + あとで / Nの + あとで / あとで + V。「〜あとで」 dùng để diễn tả một hành động xảy ra sau khi một hành động hoặc sự việc khác đã hoàn thành, mang nghĩa 'sau khi..., sau...'. Với động từ, dùng thể た trước 「あとで」; với danh từ dùng 「Nのあとで」. 「あとで」 cũng có thể đứng độc lập với nghĩa 'lát nữa, sau đó'. Cần phân biệt với 「〜てから」: cả hai đều diễn tả thứ tự trước sau, nhưng 「てから」 nhấn mạnh hành động thứ hai được thực hiện sau khi hành động thứ nhất hoàn thành, còn 「あとで」 đơn giản xác định thời điểm 'sau khi'.","sourceLesson":34,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-34","sourceRecordId":"grammar-34-3"},{"id":"hn-grammar-34-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「朝ごはんを食べないで、会社へ行きました。」","options":["〜ないほうがいい","〜なら","〜ている②","〜ないで"],"answer":3,"explanation":"〜ないで：Không làm... mà...; làm... mà không... 形：Vない + で + V。「〜ないで」 dùng để diễn tả việc thực hiện một hành động trong khi không thực hiện một hành động khác, mang nghĩa 'không làm A mà làm B' hoặc 'làm B mà không làm A'. Trong bài này, mẫu thường được dùng để diễn tả cách thức hoặc trạng thái đi kèm của hành động chính. Ví dụ 「砂糖を入れないで飲みます」 nghĩa là 'uống mà không cho đường'. Cần phân biệt với 「〜なくて」: 「〜ないで」 thường diễn tả việc chủ động không làm A rồi làm B, trong khi 「〜なくて」 thường dùng để nối trạng thái hoặc diễn tả nguyên nhân.","sourceLesson":34,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-34","sourceRecordId":"grammar-34-4"},{"id":"hn-grammar-35-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「時間があれば、旅行に行きたいです。」","options":["お〜ください","〜れる・〜られる（可能形）","〜ば","〜にくい"],"answer":2,"explanation":"〜ば：Nếu... thì...; hễ... thì... 形：五段動詞: う段→え段 + ば / 一段動詞: る→れば / する→すれば / 来る→来れば / Aい: い→ければ / Na・N: なら（ば）。「〜ば」 là thể điều kiện dùng để diễn tả rằng nếu điều kiện ở vế trước được đáp ứng thì kết quả ở vế sau sẽ xảy ra, mang nghĩa 'nếu... thì...'. Với động từ nhóm I, đổi âm cuối sang hàng え rồi thêm 「ば」, như 「行く→行けば」「読む→読めば」. Với động từ nhóm II, đổi 「る」 thành 「れば」. Tính từ い đổi 「い」 thành 「ければ」, như 「安い→安ければ」. 「〜ば」 thường được dùng với quan hệ điều kiện logic, quy luật hoặc khi kết quả phụ thuộc vào điều kiện phía trước.","sourceLesson":35,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-35","sourceRecordId":"grammar-35-1"},{"id":"hn-grammar-35-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「雨が降ったら、家にいます。」","options":["〜のに（逆接）","〜がする","あと・あとのN","〜たら"],"answer":3,"explanation":"〜たら：Nếu... thì...; khi... thì...; sau khi... thì... 形：Vた + ら / Aい → Aかったら / Na・N + だったら。「〜たら」 là mẫu điều kiện có phạm vi sử dụng rất rộng. Nó có thể diễn tả điều kiện giả định 'nếu...', hoặc một sự việc xảy ra sau khi điều kiện phía trước hoàn thành, mang nghĩa 'khi/sau khi...'. Điểm nổi bật của 「たら」 là vế sau có thể chứa ý chí, lời mời, yêu cầu, mệnh lệnh hoặc mong muốn của người nói. Vì vậy, trong nhiều tình huống hội thoại, 「たら」 linh hoạt hơn 「と」 và 「ば」.","sourceLesson":35,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-35","sourceRecordId":"grammar-35-2"},{"id":"hn-grammar-35-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「春になると、暖かくなります。」","options":["いらっしゃる","〜と","Vれる・られる（受身形）","〜やすい"],"answer":1,"explanation":"〜と：Nếu... thì...; cứ... là...; khi... thì... 形：V辞書形・Vない形 + と / Aい + と / Na・N + だ + と。「〜と」 dùng khi một kết quả xảy ra một cách tự nhiên, tất yếu hoặc lặp lại mỗi khi điều kiện phía trước xảy ra. Nó thường được dùng cho quy luật tự nhiên, máy móc, thói quen và chỉ đường. Vế sau của 「と」 về cơ bản không thích hợp với mệnh lệnh, lời nhờ vả, lời mời hoặc ý chí chủ động của người nói. Ví dụ 「春になると、暖かくなります」 diễn tả một kết quả tự nhiên.","sourceLesson":35,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-35","sourceRecordId":"grammar-35-3"},{"id":"hn-grammar-35-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「分からないときは、先生に聞けばいいです。」","options":["〜そう","〜ばいい","Vよう（意向形）","〜すぎる"],"answer":1,"explanation":"〜ばいい：Nên...; chỉ cần... là được; làm... thì tốt 形：Vば + いいです / 疑問詞 + Vば + いいですか。「〜ばいい」 dùng để nói rằng chỉ cần thực hiện một hành động hoặc đáp ứng một điều kiện là được. Nó thường được dùng để đưa ra lời khuyên, giải pháp hoặc hướng dẫn, mang nghĩa 'nên...', 'chỉ cần... là được'. Mẫu 「どうすればいいですか」 hoặc 「疑問詞＋Vばいいですか」 rất thường dùng để hỏi nên làm gì hoặc làm như thế nào.","sourceLesson":35,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-35","sourceRecordId":"grammar-35-4"},{"id":"hn-grammar-35-5","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「日本へ行くなら、京都にも行ったほうがいいです。」","options":["〜ながら","〜のが上手","〜なら","V辞書形 + な"],"answer":2,"explanation":"〜なら：Nếu là...; nếu...; nếu đúng là trường hợp đó; còn về... 形：V普通形 + なら / Aい普通形 + なら / Na + なら / N + なら。「〜なら」 dùng để đặt ra điều kiện dựa trên thông tin, chủ đề hoặc tình huống đã được nhắc đến, mang nghĩa 'nếu là..., nếu đúng là..., nếu vậy thì...'. Nó đặc biệt thường được dùng khi người nói nghe một thông tin rồi dựa vào thông tin đó để đưa ra lời khuyên, ý kiến hoặc đề nghị. Ví dụ, khi nghe người khác nói muốn đi Nhật, có thể nói 「日本へ行くなら、京都もいいですよ」. Khác với 「たら」, điều kiện 「なら」 không nhất thiết phải xảy ra trước hành động ở vế sau.","sourceLesson":35,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-35","sourceRecordId":"grammar-35-5"},{"id":"hn-grammar-35-6","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「日本語は勉強すればするほど、おもしろくなります。」","options":["〜ようにする","〜ば〜ほど","いたす","Vてくださる"],"answer":1,"explanation":"〜ば〜ほど：Càng... càng... 形：Vば + V辞書形 + ほど / Aければ + Aい + ほど / Naなら + Naな + ほど。「〜ば〜ほど」 diễn tả sự thay đổi theo tỷ lệ: khi mức độ hoặc hành động ở vế trước tăng lên thì mức độ ở vế sau cũng thay đổi tương ứng, mang nghĩa 'càng... càng...'. Với động từ, thường lặp lại cùng một động từ như 「勉強すればするほど」. Với tính từ い dùng dạng 「〜ければ〜いほど」, như 「安ければ安いほど」. Với tính từ な có thể dùng 「〜なら〜なほど」. Đây là mẫu thường dùng để diễn tả mối quan hệ tỷ lệ giữa hai mức độ.","sourceLesson":35,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-35","sourceRecordId":"grammar-35-6"},{"id":"hn-grammar-36-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「日本語が話せるように、毎日練習しています。」","options":["〜のが好き","〜ながら","〜ように","それで"],"answer":2,"explanation":"〜ように：Để...; sao cho...; để có thể...; để không... 形：V辞書形 + ように / Vない形 + ように。「〜ように」 dùng để diễn tả mục đích hoặc kết quả mà người nói muốn đạt được, mang nghĩa 'để..., sao cho...'. Mẫu này đặc biệt thường dùng khi vế trước là động từ chỉ khả năng hoặc một trạng thái không hoàn toàn phụ thuộc trực tiếp vào ý chí của người nói, như 「できる」「見える」「聞こえる」「分かる」. Dạng phủ định 「Vない＋ように」 mang nghĩa 'để không...'. Cần phân biệt với 「〜ために」: 「ために」 thường dùng với hành động có chủ ý và mục đích trực tiếp, còn 「ように」 thường hướng tới khả năng, trạng thái hoặc kết quả mong muốn.","sourceLesson":36,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-36","sourceRecordId":"grammar-36-1"},{"id":"hn-grammar-36-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「日本語が少し話せるようになりました。」","options":["〜ようになる","疑問詞 + 〜か","〜てくる","〜のに（用途）"],"answer":0,"explanation":"〜ようになる：Trở nên có thể...; bắt đầu...; dần trở thành trạng thái... 形：V辞書形 + ようになります / Vない形 + ようになります。「〜ようになります」 diễn tả một sự thay đổi về khả năng, thói quen hoặc trạng thái theo thời gian, mang nghĩa 'trở nên..., bắt đầu có thể...'. 「V辞書形＋ようになる」 thường chỉ việc trước đây không làm hoặc không thể làm nhưng sau một quá trình thì bắt đầu làm hoặc có thể làm được. 「Vない＋ようになる」 diễn tả sự thay đổi thành trạng thái không còn làm một việc nữa. Khi nói về khả năng, mẫu này rất thường đi với thể khả năng như 「話せるようになる」「泳げるようになる」.","sourceLesson":36,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-36","sourceRecordId":"grammar-36-2"},{"id":"hn-grammar-36-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「毎日、日本語を話すようにしています。」","options":["聞こえる","さ（感動詞）","ずっと①","〜ようにする"],"answer":3,"explanation":"〜ようにする：Cố gắng...; cố sao cho...; chú ý để...; đảm bảo rằng... 形：V辞書形 + ようにします / Vない形 + ようにします。「〜ようにします」 dùng để diễn tả sự cố gắng có ý thức của người nói nhằm tạo hoặc duy trì một thói quen, hoặc để một việc được thực hiện hay tránh xảy ra, mang nghĩa 'cố gắng..., chú ý để..., cố sao cho...'. 「V辞書形＋ようにする」 là cố gắng thực hiện hành động, còn 「Vない＋ようにする」 là cố gắng tránh hành động đó. Dạng 「〜ようにしています」 thường nhấn mạnh rằng người nói đang duy trì sự cố gắng đó như một thói quen thường xuyên.","sourceLesson":36,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-36","sourceRecordId":"grammar-36-3"},{"id":"hn-grammar-36-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「休みの日は、映画を見るとか、買い物をするとかします。」","options":["〜なくて","〜てみる","〜そう","〜とか〜とか"],"answer":3,"explanation":"〜とか〜とか：Chẳng hạn như...; ví dụ như...; nào là... nào là... 形：N + とか + N + とか / V普通形 + とか + V普通形 + とか。「〜とか〜とか」 dùng để đưa ra một vài ví dụ tiêu biểu trong số nhiều sự vật hoặc hành động, mang nghĩa 'chẳng hạn như..., ví dụ như..., nào là... nào là...'. Danh sách được nêu bằng 「とか」 không phải là danh sách đầy đủ; người nói chỉ chọn một số ví dụ. Nó có thể nối danh từ hoặc các hành động. So với 「や〜など」, 「とか」 thường mang sắc thái hội thoại và thân mật hơn.","sourceLesson":36,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-36","sourceRecordId":"grammar-36-4"},{"id":"hn-grammar-36-5","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「一人に二つずつ配ってください。」","options":["〜のが下手","〜ずつ","〜ていた","いらっしゃる"],"answer":1,"explanation":"〜ずつ：Mỗi...; từng... một; mỗi lần...; dần dần từng chút một 形：数量詞 + ずつ / 少し + ずつ。「〜ずつ」 đứng sau từ chỉ số lượng để diễn tả sự phân chia đồng đều, lặp lại cùng một lượng hoặc thay đổi từng bước, mang nghĩa 'mỗi..., từng... một, mỗi lần...'. Ví dụ 「一人に二つずつ」 là 'mỗi người hai cái'. 「少しずつ」 có nghĩa 'từng chút một, dần dần' và thường dùng để diễn tả một sự thay đổi diễn ra từ từ. 「ずつ」 không chỉ dùng cho đồ vật mà còn có thể dùng với người, thời gian, số lần và nhiều đơn vị số lượng khác.","sourceLesson":36,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-36","sourceRecordId":"grammar-36-5"},{"id":"hn-grammar-37-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「私は先生に褒められました。」","options":["〜のは・〜のが","〜ないで","〜はずだ","Vれる・られる（受身形）"],"answer":3,"explanation":"Vれる・られる（受身形）：Bị/được...; bị ai đó làm...; chịu ảnh hưởng bởi hành động của người khác 形：五段動詞: う段→あ段 + れる / 一段動詞: る→られる / する→される / 来る→来られる。「受身形」 là thể bị động, dùng khi chủ ngữ là người hoặc vật nhận hành động. Với câu bị động trực tiếp, người thực hiện hành động thường được đánh dấu bằng 「に」, như 「先生は私を褒めました→私は先生に褒められました」. Ngoài nghĩa trung tính 'được/bị...', tiếng Nhật còn thường dùng bị động để diễn tả người nói bị ảnh hưởng, phiền toái hoặc gặp điều không mong muốn do hành động của người khác, như 「私は弟にケーキを食べられました」 nghĩa là 'tôi bị em trai ăn mất bánh'. Với sự kiện, phát minh hoặc công trình, thể bị động cũng thường được dùng để trình bày sự việc một cách khách quan.","sourceLesson":37,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-37","sourceRecordId":"grammar-37-1"},{"id":"hn-grammar-37-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「この机は木でできています。」","options":["V辞書形 + な","まだ〜ていません","Vてやる・Vてさしあげる","〜でできる・〜からできる"],"answer":3,"explanation":"〜でできる・〜からできる：Được làm bằng...; được làm từ...; được tạo ra từ... 形：N + で + できています / N + から + できています。「〜でできています」 và 「〜からできています」 dùng để nói về nguyên liệu hoặc vật liệu tạo nên một vật. 「Nでできています」 thường dùng khi vật liệu ban đầu vẫn có thể nhận ra tương đối rõ trong sản phẩm, như bàn làm bằng gỗ hoặc túi làm bằng giấy. 「Nからできています」 thường dùng khi nguyên liệu đã trải qua quá trình biến đổi và hình dạng ban đầu không còn rõ, mang nghĩa 'được làm từ...'. Trong mẫu này, 「できる」 không mang nghĩa 'có thể' mà mang nghĩa 'được tạo thành, được làm ra'.","sourceLesson":37,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-37","sourceRecordId":"grammar-37-2"},{"id":"hn-grammar-37-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「今、会議中です。」","options":["〜中","〜がする","N1がN2にN3をくださる","〜のが上手"],"answer":0,"explanation":"〜中：Đang trong lúc...; trong suốt...; đang trong quá trình... 形：N + 中（ちゅう） / Vている + 最中（さいちゅう）。「〜中（ちゅう）」 gắn sau một số danh từ chỉ hoạt động hoặc sự kiện để diễn tả rằng hoạt động đó đang diễn ra, mang nghĩa 'đang trong lúc..., đang trong quá trình...'. Ví dụ thường gặp là 「会議中」「授業中」「仕事中」「電話中」. Nó cũng có thể xuất hiện trong các thông báo như 「使用中」 là 'đang sử dụng'. Khi muốn nhấn mạnh 'đúng ngay giữa lúc đang làm...', tiếng Nhật thường dùng 「〜最中（さいちゅう）」 với dạng 「Vている最中」 hoặc 「Nの最中」. Cần chú ý chữ 「中」 còn có cách đọc 「じゅう」 với nghĩa 'suốt/toàn bộ', như 「一日中」 là 'suốt cả ngày'.","sourceLesson":37,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-37","sourceRecordId":"grammar-37-3"},{"id":"hn-grammar-38-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「日本語を勉強するのはおもしろいです。」","options":["N1がN2にN3をくださる","〜のは・〜のが","V辞書形 + な","〜てくる"],"answer":1,"explanation":"〜のは・〜のが：Việc...; chuyện...; cái mà... 形：V普通形 + の + 助詞（は・が・を など）。「の」 đặt sau động từ dạng thông thường để danh từ hóa cả mệnh đề, biến một hành động hoặc sự việc thành 'việc..., chuyện...'. Sau khi được danh từ hóa, cụm 「V普通形＋の」 có thể đi với các trợ từ như 「は」「が」「を」 giống một danh từ. 「〜のは」 thường đưa hành động hoặc sự việc lên làm chủ đề, còn 「〜のが」 thường đánh dấu nó là chủ ngữ hoặc đối tượng của các mẫu như 「好き」「上手」「下手」. Ví dụ 「本を読むのはおもしろいです」 nghĩa là 'việc đọc sách thì thú vị'.","sourceLesson":38,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-38","sourceRecordId":"grammar-38-1"},{"id":"hn-grammar-38-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「私は音楽を聞くのが好きです。」","options":["〜のが好き","〜中","〜ていただけませんか","〜のは・〜のが"],"answer":0,"explanation":"〜のが好き：Thích làm...; thích việc... 形：V普通形 + のが + 好きです。「〜のが好きです」 dùng để diễn tả sở thích đối với một hành động hoặc hoạt động, mang nghĩa 'thích làm...'. 「の」 danh từ hóa động từ đứng trước, còn 「が好きです」 diễn tả sự yêu thích. Vì vậy, thay vì chỉ nói thích một đồ vật như 「音楽が好きです」, có thể nói thích thực hiện một hành động như 「音楽を聞くのが好きです」. Dạng mạnh hơn có thể dùng 「大好きです」.","sourceLesson":38,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-38","sourceRecordId":"grammar-38-2"},{"id":"hn-grammar-38-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「田中さんは料理を作るのが上手です。」","options":["あと・あとのN","〜のに（逆接）","〜のが上手","〜てくる"],"answer":2,"explanation":"〜のが上手：Giỏi làm...; thành thạo việc... 形：V普通形 + のが + 上手です。「〜のが上手です」 dùng để nói một người giỏi hoặc thành thạo thực hiện một hành động nào đó. 「の」 biến hành động thành một danh từ, sau đó dùng với 「が上手です」. Mẫu này thường được dùng để nhận xét khả năng của người khác. Khi nói về chính mình, người Nhật thường tránh trực tiếp dùng 「上手」 vì có thể mang sắc thái tự khen; trong trường hợp đó có thể dùng những cách diễn đạt như 「得意です」 tùy ngữ cảnh.","sourceLesson":38,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-38","sourceRecordId":"grammar-38-3"},{"id":"hn-grammar-38-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「私は歌を歌うのが下手です。」","options":["Vて、〜（原因・理由）","疑問詞 + 〜か","〜のが下手","〜ておく"],"answer":2,"explanation":"〜のが下手：Kém làm...; không giỏi...; vụng về trong việc... 形：V普通形 + のが + 下手です。「〜のが下手です」 dùng để diễn tả một người không giỏi hoặc thiếu kỹ năng trong việc thực hiện một hành động, mang nghĩa 'kém..., không giỏi...'. 「の」 danh từ hóa hành động, sau đó 「が下手です」 đánh giá kỹ năng đối với hành động đó. 「下手」 nói khá trực tiếp về sự kém kỹ năng, vì vậy khi nhận xét người khác cần chú ý ngữ cảnh để tránh gây cảm giác thiếu lịch sự.","sourceLesson":38,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-38","sourceRecordId":"grammar-38-4"},{"id":"hn-grammar-38-5","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「赤いのは私のかばんです。」","options":["〜ので","〜てある","A + の・A + のは","N1にN2をやる・さしあげる"],"answer":2,"explanation":"A + の・A + のは：Cái...; cái mà...; cái có đặc điểm... 形：Aい + の / Na + なの / Aい + のは〜 / Na + なのは〜。「の」 có thể thay thế một danh từ đã được biết hoặc có thể hiểu từ ngữ cảnh, tương đương với 'cái..., cái mà...' trong tiếng Việt. Với tính từ い, dùng trực tiếp 「Aい＋の」 như 「赤いの」 là 'cái màu đỏ'. Với tính từ な, dùng 「Na＋なの」 như 「きれいなの」 là 'cái đẹp/sạch'. Khi thêm 「は」 thành 「〜のは」, cụm này được đưa lên làm chủ đề. Cách dùng này giúp tránh lặp lại danh từ đã được nhắc đến trước đó.","sourceLesson":38,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-38","sourceRecordId":"grammar-38-5"},{"id":"hn-grammar-38-6","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「毎日ちゃんと朝ごはんを食べています。」","options":["Vて、〜（原因・理由）","V辞書形 + な","ちゃんと・きちんと","〜でできる・〜からできる"],"answer":2,"explanation":"ちゃんと・きちんと：Đàng hoàng; đúng cách; cẩn thận; chỉnh tề; gọn gàng 形：ちゃんと + V / きちんと + V / ちゃんとした + N / きちんとした + N。「ちゃんと」 và 「きちんと」 đều diễn tả việc làm một điều gì đó đúng cách, đầy đủ hoặc nghiêm túc. 「ちゃんと」 rất phổ biến trong hội thoại và có thể mang nghĩa 'đàng hoàng, đúng cách, đầy đủ', như 「ちゃんと勉強する」 là 'học hành đàng hoàng'. 「きちんと」 cũng có nghĩa tương tự nhưng thường nhấn mạnh sự chính xác, ngăn nắp, có trật tự hoặc chỉnh tề, như 「きちんと並べる」 là 'xếp ngay ngắn'. Tùy ngữ cảnh, hai từ có thể thay thế nhau, nhưng 「きちんと」 thường tạo cảm giác gọn gàng và quy củ hơn.","sourceLesson":38,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-38","sourceRecordId":"grammar-38-6"},{"id":"hn-grammar-39-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「友達に会えて、うれしかったです。」","options":["〜かどうか","〜にくい","〜かもしれない","Vて、〜（原因・理由）"],"answer":3,"explanation":"Vて、〜（原因・理由）：Vì... nên...; do... mà...; ... và vì thế... 形：Vて + 結果 / Aい → Aくて + 結果 / Na・N + で + 結果。「〜て／〜で」 có thể dùng để nối nguyên nhân với kết quả, mang nghĩa 'vì... nên..., do... mà...'. Khác với cách dùng 「Vて」 để nối các hành động theo thứ tự, ở đây vế trước là nguyên nhân dẫn đến trạng thái hoặc kết quả ở vế sau. Mẫu này thường dùng khi kết quả là cảm xúc, trạng thái, khả năng hoặc một sự việc xảy ra tự nhiên, như 「会えて、うれしいです」. Vế sau thường không dùng những biểu hiện mang ý chí mạnh như mệnh lệnh, lời nhờ vả hoặc lời mời.","sourceLesson":39,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-39","sourceRecordId":"grammar-39-1"},{"id":"hn-grammar-39-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「お金がなくて、旅行に行けません。」","options":["〜ておく","〜とか〜とか","〜なくて","〜ないほうがいい"],"answer":2,"explanation":"〜なくて：Không... và...; vì không... nên...; không... mà... 形：Vない → Vなくて / Aい: 〜くない → 〜くなくて / Na・N: 〜ではない → 〜ではなくて。「〜なくて」 là dạng nối của thể phủ định, dùng để nối một trạng thái hoặc sự việc phủ định với nội dung phía sau. Nó có thể mang nghĩa 'không A và B' hoặc diễn tả nguyên nhân 'vì không A nên B'. Ví dụ 「お金がなくて、買えません」 nghĩa là 'vì không có tiền nên không thể mua'. Cần phân biệt với 「〜ないで」: 「ないで」 thường mang nghĩa 'không làm A mà làm B', trong đó người nói chủ động không thực hiện hành động A; còn 「なくて」 thường nối trạng thái hoặc diễn tả nguyên nhân dẫn đến kết quả.","sourceLesson":39,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-39","sourceRecordId":"grammar-39-2"},{"id":"hn-grammar-39-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「雨が降っているので、出かけません。」","options":["〜ので","数量詞 + も","まだ","〜のは・〜のが"],"answer":0,"explanation":"〜ので：Vì...; bởi vì...; do... nên... 形：V普通形 + ので / Aい普通形 + ので / Na + なので / N + なので。「〜ので」 dùng để nêu nguyên nhân hoặc lý do, mang nghĩa 'vì..., bởi vì..., do... nên...'. So với 「から」, 「ので」 thường có sắc thái mềm mại, khách quan và lịch sự hơn, vì vậy thường được dùng khi giải thích hoàn cảnh, xin phép, từ chối hoặc đưa ra lý do mà người nói muốn tránh tạo cảm giác áp đặt. Trước 「ので」, động từ và tính từ い dùng dạng thông thường; tính từ な và danh từ ở hiện tại khẳng định dùng 「なので」. Trong hội thoại thân mật, 「ので」 đôi khi được rút gọn thành 「んで」.","sourceLesson":39,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-39","sourceRecordId":"grammar-39-3"},{"id":"hn-grammar-39-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「学校へ行く途中で、先生に会いました。」","options":["〜たほうがいい","〜途中に・〜途中で","〜ために","〜ないで"],"answer":1,"explanation":"〜途中に・〜途中で：Trên đường...; giữa chừng...; trong lúc đang...; đang trong quá trình... 形：V辞書形 + 途中で／途中に / Vている + 途中で／途中に / Nの + 途中で／途中に。「途中」 diễn tả một thời điểm hoặc vị trí khi một hành động, quá trình hay hành trình vẫn chưa hoàn thành, mang nghĩa 'giữa chừng, đang trong quá trình, trên đường'. 「〜途中で」 thường nhấn mạnh hoàn cảnh hoặc điểm mà một hành động/sự việc khác xảy ra trong quá trình đó. 「〜途中に」 thường nhấn mạnh thời điểm hoặc địa điểm nằm trên đường hay trong quá trình. Ví dụ 「学校へ行く途中で」 là 'trên đường đi học'. Không nên nhầm với 「〜中」: 「途中」 nhấn mạnh một điểm nằm giữa điểm bắt đầu và kết thúc của một quá trình.","sourceLesson":39,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-39","sourceRecordId":"grammar-39-4"},{"id":"hn-grammar-40-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「田中さんがどこにいるか分かりません。」","options":["〜によると・〜によれば","〜でしょう","疑問詞 + 〜か","〜ようだ"],"answer":2,"explanation":"疑問詞 + 〜か：...ai/cái gì/ở đâu/khi nào...; đưa câu hỏi vào trong một câu lớn 形：疑問詞 + 普通形 + か + V / 疑問詞 + Na・N + か + V。「疑問詞＋〜か」 dùng để đưa một câu hỏi có từ nghi vấn như 「何」「誰」「どこ」「いつ」「どう」「どれ」 vào bên trong một câu lớn, tạo thành câu hỏi gián tiếp. Phần trước 「か」 dùng dạng thông thường và không đảo cấu trúc như tiếng Việt. Ví dụ 「田中さんはどこにいますか」 là câu hỏi trực tiếp, còn khi đưa vào câu 「田中さんがどこにいるか分かりません」 thì có nghĩa 'tôi không biết anh Tanaka đang ở đâu'. Sau mệnh đề 「〜か」 thường gặp các động từ như 「分かる」「知る」「覚える」「調べる」「聞く」.","sourceLesson":40,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-40","sourceRecordId":"grammar-40-1"},{"id":"hn-grammar-40-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「明日雨が降るかどうか分かりません。」","options":["〜ながら","まだ〜ていません","〜かどうか","〜でしょう"],"answer":2,"explanation":"〜かどうか：Có... hay không; liệu... hay không; có phải... không 形：V普通形 + かどうか / Aい普通形 + かどうか / Na・N + かどうか。「〜かどうか」 dùng để đưa một câu hỏi Có/Không vào bên trong một câu lớn, mang nghĩa 'liệu... hay không', 'có... hay không'. Khác với 「疑問詞＋か」 dùng khi câu hỏi có từ nghi vấn như ai, cái gì, ở đâu, khi nào, 「かどうか」 dùng khi chỉ có hai khả năng: đúng hoặc không đúng, có hoặc không. Với tính từ な và danh từ ở hiện tại khẳng định, thường không dùng 「だ」 trước 「かどうか」.","sourceLesson":40,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-40","sourceRecordId":"grammar-40-2"},{"id":"hn-grammar-40-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「この料理を食べてみます。」","options":["〜てしまう・〜ちゃう","〜か〜","〜にくい","〜てみる"],"answer":3,"explanation":"〜てみる：Thử làm...; làm thử xem... 形：Vて + みます。「〜てみます」 dùng khi thử thực hiện một hành động để xem kết quả, cảm giác hoặc tình hình như thế nào, mang nghĩa 'thử làm...'. 「みる」 trong mẫu này không mang nghĩa thông thường là 'nhìn, xem' mà đóng vai trò bổ trợ cho động từ đứng trước. Ví dụ 「食べてみます」 là 'ăn thử', 「使ってみます」 là 'dùng thử'. Dạng 「〜てみたいです」 diễn tả mong muốn thử làm một việc nào đó.","sourceLesson":40,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-40","sourceRecordId":"grammar-40-3"},{"id":"hn-grammar-40-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「この山の高さは3,000メートルです。」","options":["〜ばいい","〜のが上手","〜てある","A + さ"],"answer":3,"explanation":"A + さ：Độ...; mức độ...; tính...; biến tính từ thành danh từ 形：Aい: い → さ / Na + さ。Hậu tố 「〜さ」 được gắn vào tính từ để biến tính từ thành danh từ chỉ mức độ hoặc tính chất, tương đương các cách nói như 'độ..., mức độ..., tính...' trong tiếng Việt. Với tính từ い, bỏ 「い」 rồi thêm 「さ」, như 「高い→高さ」「長い→長さ」「重い→重さ」. Với tính từ な, thêm trực tiếp 「さ」, như 「便利→便利さ」「静か→静かさ」. Một trường hợp đặc biệt thường gặp là 「いい→よさ」. Danh từ tạo bởi 「〜さ」 có thể sử dụng với các trợ từ như một danh từ bình thường.","sourceLesson":40,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-40","sourceRecordId":"grammar-40-4"},{"id":"hn-grammar-40-5","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「さあ、始めましょう。」","options":["〜予定だ","もしかしたら","まだ","さ（感動詞）"],"answer":3,"explanation":"さ（感動詞）：Nào...; được rồi...; xem nào...; thì...; ấy mà... 形：さ / さあ + 文。「さ」 hoặc 「さあ」 với tư cách là cảm động từ được dùng trong hội thoại để mở đầu lời nói, thúc giục hành động, chuyển sang việc tiếp theo hoặc thể hiện người nói đang suy nghĩ. Tùy ngữ cảnh, nó có thể tương đương 'nào, được rồi, xem nào, để xem...'. 「さあ」 thường đứng độc lập hoặc ở đầu câu như 「さあ、行きましょう」. Khi được hỏi một điều mà người nói không biết chắc, 「さあ」 cũng có thể mang sắc thái 'ừm, tôi cũng không biết, để xem...'. Cần phân biệt cách dùng này với hậu tố 「〜さ」 dùng để biến tính từ thành danh từ.","sourceLesson":40,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-40","sourceRecordId":"grammar-40-5"},{"id":"hn-grammar-41-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「私は犬にえさをやりました。」","options":["〜がする","N1にN2をやる・さしあげる","〜はずだ","Vてくださる"],"answer":1,"explanation":"N1にN2をやる・さしあげる：Cho...; biếu/tặng... (phân biệt theo quan hệ giữa người cho và người nhận) 形：N1（受け手）に + N2を + やります／さしあげます。「やります」 và 「さしあげます」 đều thuộc nhóm biểu hiện cho đồ vật từ phía người nói sang người khác. 「やります」 thường dùng khi người nhận là động vật hoặc thực vật, như cho chó thức ăn hoặc tưới nước cho cây. Trước đây 「やります」 cũng được dùng với người có địa vị hoặc tuổi tác thấp hơn, nhưng trong tiếng Nhật hiện đại, khi người nhận là người thì 「あげます」 thường tự nhiên hơn. 「さしあげます」 là khiêm nhường ngữ của 「あげます」, dùng khi người nói cho hoặc biếu một người cần được kính trọng như giáo viên, cấp trên hoặc khách hàng. Người nhận được đánh dấu bằng 「に」, còn vật được cho dùng 「を」.","sourceLesson":41,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-41","sourceRecordId":"grammar-41-1"},{"id":"hn-grammar-41-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「私は部長にお土産をいただきました。」","options":["いたす","〜のが上手","N1にN2をいただく","〜にする"],"answer":2,"explanation":"N1にN2をいただく：Được nhận... từ...; nhận... (khiêm nhường ngữ) 形：（私は）N1に／から + N2を + いただきます。「いただきます」 là khiêm nhường ngữ của 「もらいます」, dùng khi người nói hoặc người thuộc phía mình nhận một vật từ người cần được kính trọng, chẳng hạn giáo viên, cấp trên hoặc khách hàng. Bằng cách hạ thấp phía người nhận, người nói thể hiện sự kính trọng đối với người cho. Người cho thường được đánh dấu bằng 「に」 hoặc 「から」, còn vật nhận được dùng 「を」. Khi nói về việc nhận từ tổ chức, công ty hoặc trường học, 「から」 thường được sử dụng tự nhiên hơn.","sourceLesson":41,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-41","sourceRecordId":"grammar-41-2"},{"id":"hn-grammar-41-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「部長が私にお土産をくださいました。」","options":["〜やすい","〜か〜","N1がN2にN3をくださる","〜ようだ"],"answer":2,"explanation":"N1がN2にN3をくださる：Ai đó cho/tặng tôi hoặc người thuộc phía tôi... (kính ngữ) 形：N1（与え手）が + 私／私側の人に + N3を + くださいます。「くださいます」 là kính ngữ của 「くれます」, dùng khi một người cần được kính trọng cho người nói hoặc người thuộc phía người nói một vật nào đó. Người cho được đánh dấu bằng 「が」 hoặc 「は」, người nhận dùng 「に」 và vật được cho dùng 「を」. Người nhận không nhất thiết phải là chính người nói; có thể là thành viên gia đình hoặc người thuộc nhóm của người nói. Dạng lịch sự đặc biệt là 「くださいます」 chứ không phải 「くださります」.","sourceLesson":41,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-41","sourceRecordId":"grammar-41-3"},{"id":"hn-grammar-41-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「私は犬を散歩に連れて行ってやりました。」","options":["Vてやる・Vてさしあげる","Vて、〜（原因・理由）","〜ながら","〜ばいい"],"answer":0,"explanation":"Vてやる・Vてさしあげる：Làm... cho ai; làm giúp...; làm cho động vật... 形：Vて + やります／さしあげます。「Vてやります」 diễn tả người nói thực hiện một hành động vì lợi ích của người có vị thế thấp hơn hoặc động vật. Tuy nhiên, với người, tiếng Nhật hiện đại thường dùng 「Vてあげます」 tự nhiên hơn. 「Vてさしあげます」 là dạng khiêm nhường của 「Vてあげます」 và về mặt ngữ pháp có thể dùng khi làm việc gì đó cho người trên. Tuy nhiên, nếu nói trực tiếp với người trên, mẫu này có thể tạo cảm giác người nói đang nhấn mạnh rằng mình 'làm ơn' cho họ, vì vậy thường tránh dùng. Trong tình huống đó, các cách nói khiêm nhường như 「お持ちしましょうか」 tự nhiên và lịch sự hơn.","sourceLesson":41,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-41","sourceRecordId":"grammar-41-4"},{"id":"hn-grammar-41-5","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「私は課長に手紙の間違いを直していただきました。」","options":["Vていただく","いらっしゃる","〜たら","〜ておく"],"answer":0,"explanation":"Vていただく：Được ai đó làm... cho; được người trên giúp làm... (khiêm nhường) 形：（私は）Nに + Vて + いただきます。「Vていただきます」 là cách nói khiêm nhường của 「Vてもらいます」. Mẫu này diễn tả người nói hoặc người thuộc phía mình nhận được lợi ích từ hành động của một người cần được kính trọng. Người thực hiện hành động được đánh dấu bằng 「に」. Trọng tâm của câu nằm ở phía người nhận: 'tôi được người đó làm V cho'. Vì vậy, 「先生に教えていただきました」 có nghĩa là 'tôi đã được thầy/cô dạy cho'. Mẫu này thường được dùng để thể hiện lòng biết ơn và sự kính trọng đối với người đã thực hiện hành động.","sourceLesson":41,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-41","sourceRecordId":"grammar-41-5"},{"id":"hn-grammar-41-6","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「先生が日本語を教えてくださいました。」","options":["Vてくださる","それに","〜と","〜場合は"],"answer":0,"explanation":"Vてくださる：Ai đó làm... cho tôi/người phía tôi (kính ngữ) 形：Nが／は + （私／私側の人に）+ Vて + くださいます。「Vてくださいます」 là kính ngữ của 「Vてくれます」, dùng khi một người cần được kính trọng thực hiện một hành động có lợi cho người nói hoặc người thuộc phía người nói. Người thực hiện hành động được đánh dấu bằng 「が」 hoặc 「は」. Trọng tâm nằm ở người làm hành động, khác với 「Vていただきます」 vốn nhìn sự việc từ phía người nhận. Ví dụ 「先生が教えてくださいました」 là 'thầy/cô đã dạy cho tôi', còn 「先生に教えていただきました」 là 'tôi đã được thầy/cô dạy'. Hai câu diễn tả gần như cùng một sự việc nhưng khác góc nhìn và trợ từ.","sourceLesson":41,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-41","sourceRecordId":"grammar-41-6"},{"id":"hn-grammar-41-7","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「コピー機の使い方を教えてくださいませんか。」","options":["Vてくださいませんか","〜し、〜し","〜中","A + の・A + のは"],"answer":0,"explanation":"Vてくださいませんか：Anh/chị có thể vui lòng... được không?; có thể làm... giúp tôi được không? 形：Vて + くださいませんか。「Vてくださいませんか」 là cách yêu cầu hoặc nhờ người khác làm một việc một cách lịch sự. Về hình thức, đây là dạng nghi vấn phủ định của 「Vてくださいます」 và có thể hiểu là 'anh/chị có thể vui lòng làm V cho tôi được không?'. Cách nói này mềm và lịch sự hơn mệnh lệnh 「Vてください」. 「Vていただけませんか」 cũng dùng để nhờ vả nhưng thường khiêm nhường và lịch sự hơn. Khi trực tiếp nhờ người nghe, người thực hiện hành động thường được lược bỏ vì đã rõ là người nghe.","sourceLesson":41,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-41","sourceRecordId":"grammar-41-7"},{"id":"hn-grammar-41-8","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「田中さんが結婚のお祝いにこのお皿をくださいました。」","options":["〜途中に・〜途中で","NにV","〜すぎる","Vて、〜（原因・理由）"],"answer":1,"explanation":"NにV：Làm... để làm quà; làm... nhân dịp/kỷ niệm...; dùng cho mục đích... 形：N + に + V。「に」 trong mẫu này chỉ mục đích, dịp hoặc ý nghĩa mà một vật được mua, tặng, chọn hoặc chuẩn bị để phục vụ, thường có thể dịch là 'làm quà..., nhân dịp..., để làm...'. Các danh từ thường gặp trước 「に」 gồm 「お土産」「お祝い」「記念」「プレゼント」. Ví dụ 「結婚のお祝いに皿をあげます」 nghĩa là 'tặng đĩa làm quà mừng cưới', còn 「北海道のお土産に人形を買います」 nghĩa là 'mua búp bê làm quà lưu niệm từ Hokkaido'. 「に」 ở đây không chỉ người nhận mà chỉ mục đích hoặc danh nghĩa của món đồ/hành động.","sourceLesson":41,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-41","sourceRecordId":"grammar-41-8"},{"id":"hn-grammar-42-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「日本へ留学するために、日本語を勉強しています。」","options":["〜にする","それで","まだ〜ていません","〜ために"],"answer":3,"explanation":"〜ために：Để...; nhằm...; vì lợi ích của...; vì mục đích... 形：V辞書形 + ために / Nの + ために。「〜ために」 dùng để diễn tả mục đích của một hành động, mang nghĩa 'để..., nhằm...'. Với động từ, dùng 「V辞書形＋ために」; với danh từ, dùng 「Nの＋ために」. Khi chỉ mục đích, chủ thể của hành động trước và sau 「ために」 thường là cùng một người, và động từ phía trước thường là hành động có ý chí, có thể chủ động thực hiện. 「Nのために」 còn có thể mang nghĩa 'vì lợi ích của N, vì N'. Cần phân biệt với 「〜ように」: 「ために」 thường dùng khi người nói chủ động thực hiện hành động để đạt mục tiêu, còn 「ように」 thường dùng khi mục tiêu là khả năng, trạng thái hoặc kết quả không hoàn toàn kiểm soát trực tiếp được.","sourceLesson":42,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-42","sourceRecordId":"grammar-42-1"},{"id":"hn-grammar-42-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「このはさみは紙を切るのに使います。」","options":["〜のに（用途）","〜でしょう","〜代わりに","疑問詞 + 〜か"],"answer":0,"explanation":"〜のに（用途）：Để...; dùng để...; cần cho việc... 形：V辞書形 + のに + 使います／便利です／必要です／いいです／役に立ちます。「〜のに」 trong bài này dùng để diễn tả mục đích sử dụng, công dụng hoặc tiêu chuẩn cần thiết cho một hành động, mang nghĩa 'để..., dùng cho việc...'. 「の」 danh từ hóa động từ, còn 「に」 chỉ mục đích hoặc công dụng. Mẫu này thường đi với các biểu hiện đánh giá hoặc công dụng như 「使います」「便利です」「必要です」「いいです」「役に立ちます」「時間がかかります」. Ví dụ 「このはさみは紙を切るのに使います」 nghĩa là 'cái kéo này dùng để cắt giấy'. Cần phân biệt với 「〜のに」 mang nghĩa 'mặc dù...' ở các bài/ngữ pháp khác.","sourceLesson":42,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-42","sourceRecordId":"grammar-42-2"},{"id":"hn-grammar-42-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「パーティーに100人も来ました。」","options":["〜と","A + さ","数量詞 + も","〜たら"],"answer":2,"explanation":"数量詞 + も：Tận...; những...; tới...; đến...; nhấn mạnh số lượng nhiều 形：数量詞 + も + 肯定文 / 疑問詞・最小数量 + も + 否定文。「も」 đứng sau từ chỉ số lượng để nhấn mạnh rằng số lượng đó nhiều hơn mức người nói dự đoán hoặc cảm thấy đáng chú ý, thường dịch là 'tận..., tới..., những...'. Ví dụ 「100人も来ました」 nghĩa là 'có tận 100 người đã đến'. Khi kết hợp với lượng tối thiểu hoặc từ nghi vấn trong câu phủ định, 「も」 có thể nhấn mạnh rằng hoàn toàn không có hoặc không đạt ngay cả mức nhỏ nhất, như 「一人も来ませんでした」 là 'không một ai đến'. Ý nghĩa cụ thể phụ thuộc vào câu khẳng định hay phủ định và ngữ cảnh.","sourceLesson":42,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-42","sourceRecordId":"grammar-42-3"},{"id":"hn-grammar-42-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「父の代わりに、私が会議に出ます。」","options":["〜かどうか","〜中","すると","〜代わりに"],"answer":3,"explanation":"〜代わりに：Thay cho...; thay vì...; đổi lại...; bù lại... 形：Nの + 代わりに / V辞書形 + 代わりに。「〜代わりに」 dùng khi một người, vật hoặc hành động thay thế cho một người, vật hoặc hành động khác, mang nghĩa 'thay cho..., thay vì...'. Với danh từ dùng 「Nの代わりに」, còn với động từ dùng 「V辞書形＋代わりに」. Mẫu này cũng có thể diễn tả sự trao đổi hoặc bù lại: người nói làm một việc và đổi lại người khác làm một việc khác. Trong cách dùng mở rộng, nó còn có thể mang nghĩa 'bù lại', dùng để nêu một mặt khác cân bằng với đặc điểm đã nói trước.","sourceLesson":42,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-42","sourceRecordId":"grammar-42-4"},{"id":"hn-grammar-43-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「このケーキはおいしそうです。」","options":["Vていただく","〜がする","〜たばかり","〜そう"],"answer":3,"explanation":"〜そう：Trông có vẻ...; có vẻ sắp...; dường như... 形：Vます → bỏ ます + そうです / Aい → bỏ い + そうです / Na + そうです。「〜そうです」 trong bài này dùng để đưa ra phán đoán dựa trên những gì người nói trực tiếp nhìn thấy hoặc cảm nhận được, mang nghĩa 'trông có vẻ..., dường như..., có vẻ sắp...'. Với động từ, bỏ 「ます」 rồi thêm 「そうです」, thường diễn tả dấu hiệu một sự việc sắp xảy ra, như 「雨が降りそうです」 là 'trông có vẻ sắp mưa'. Với tính từ い, bỏ 「い」 rồi thêm 「そうです」, như 「おいしい→おいしそうです」. Với tính từ な, thêm trực tiếp 「そうです」, như 「元気→元気そうです」. Hai trường hợp đặc biệt thường gặp là 「いい→よさそう」 và 「ない→なさそう」. Cần phân biệt với 「普通形＋そうです」 mang nghĩa 'nghe nói rằng...', là một cách dùng khác của 「そう」.","sourceLesson":43,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-43","sourceRecordId":"grammar-43-1"},{"id":"hn-grammar-43-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「だんだん寒くなってきました。」","options":["〜ておく","いたす","〜てくる","〜ないほうがいい"],"answer":2,"explanation":"〜てくる：Dần trở nên...; bắt đầu...; đã... cho đến nay; tiếp diễn đến hiện tại 形：Vて + きます / Vて + きました。「〜てくる」 ngoài nghĩa chuyển động 'làm gì rồi đến đây', còn dùng để diễn tả sự thay đổi hoặc quá trình phát triển hướng đến thời điểm hiện tại. Nó có thể chỉ một trạng thái bắt đầu xuất hiện và ngày càng rõ hơn, như 「寒くなってきました」 là 'trời bắt đầu/dần trở lạnh'. Dạng 「〜てきました」 cũng dùng khi một hành động hoặc trạng thái bắt đầu trong quá khứ và tiếp tục phát triển cho đến hiện tại, như 「日本語を勉強してきました」 là 'đã học tiếng Nhật cho đến nay'. Khi đi với hiện tượng xuất hiện gần người nói, 「雨が降ってきました」 mang nghĩa 'trời bắt đầu mưa rồi'. Cần phân biệt với 「〜ていく」: 「〜てくる」 nhìn sự thay đổi từ quá khứ hoặc thời điểm trước tiến đến hiện tại, còn 「〜ていく」 thường nhìn sự thay đổi từ hiện tại tiếp tục về tương lai.","sourceLesson":43,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-43","sourceRecordId":"grammar-43-2"},{"id":"hn-grammar-44-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「きのう、食べすぎました。」","options":["Vれる・られる（受身形）","〜のが好き","〜すぎる","〜なら"],"answer":2,"explanation":"〜すぎる：Quá...; quá mức...; làm... quá nhiều 形：Vます → bỏ ます + すぎます / Aい → bỏ い + すぎます / Na + すぎます。「〜すぎます」 dùng để diễn tả một hành động, trạng thái hoặc mức độ vượt quá giới hạn thích hợp, mang nghĩa 'quá..., quá mức..., làm quá nhiều...'. Với động từ, bỏ 「ます」 rồi thêm 「すぎます」, như 「食べます→食べすぎます」. Với tính từ い, bỏ 「い」 rồi thêm 「すぎます」, như 「高い→高すぎます」. Với tính từ な, thêm trực tiếp 「すぎます」, như 「静か→静かすぎます」. Mẫu này thường mang sắc thái tiêu cực vì mức độ đã vượt quá điều người nói cho là bình thường hoặc phù hợp.","sourceLesson":44,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-44","sourceRecordId":"grammar-44-1"},{"id":"hn-grammar-44-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「この本はとても読みやすいです。」","options":["N1がN2にN3をくださる","N1にN2をいただく","〜やすい","Vてくださる"],"answer":2,"explanation":"〜やすい：Dễ...; dễ dàng để...; có xu hướng dễ... 形：Vます → bỏ ます + やすいです。「〜やすい」 gắn vào thân động từ thể ます để diễn tả một hành động dễ thực hiện hoặc một sự việc dễ xảy ra, mang nghĩa 'dễ...'. Ví dụ 「読みやすい」 là 'dễ đọc', 「使いやすい」 là 'dễ sử dụng'. Ngoài khả năng thực hiện hành động, mẫu này còn có thể chỉ khuynh hướng dễ xảy ra, như 「このコップは割れやすい」 là 'chiếc cốc này dễ vỡ'. Sau khi kết hợp với động từ, 「〜やすい」 hoạt động giống một tính từ い nên có thể biến đổi như 「やすくない」「やすかった」.","sourceLesson":44,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-44","sourceRecordId":"grammar-44-2"},{"id":"hn-grammar-44-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「この漢字は覚えにくいです。」","options":["〜代わりに","〜と","〜にくい","Vてくださる"],"answer":2,"explanation":"〜にくい：Khó...; khó để...; không dễ... 形：Vます → bỏ ます + にくいです。「〜にくい」 gắn vào thân động từ thể ます để diễn tả một hành động khó thực hiện hoặc một sự việc khó xảy ra, mang nghĩa 'khó..., không dễ...'. Ví dụ 「読みにくい」 là 'khó đọc', 「使いにくい」 là 'khó sử dụng'. Nó thường diễn tả khó khăn do đặc điểm của đồ vật, hoàn cảnh hoặc tính chất của hành động, chứ không nhất thiết có nghĩa người thực hiện không có khả năng. Sau khi kết hợp với động từ, 「〜にくい」 hoạt động giống tính từ い và có thể chia như 「にくくない」「にくかった」. Đây là mẫu đối lập với 「〜やすい」.","sourceLesson":44,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-44","sourceRecordId":"grammar-44-3"},{"id":"hn-grammar-44-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「飲み物はコーヒーにします。」","options":["いたす","お〜する","A + さ","〜にする"],"answer":3,"explanation":"〜にする：Chọn...; quyết định chọn...; làm cho... trở thành... 形：N + にします / Na + にします / Aい → Aく + します。「〜にします」 có hai cách dùng quan trọng. Thứ nhất, nó dùng để diễn tả sự lựa chọn hoặc quyết định giữa nhiều phương án, mang nghĩa 'chọn..., quyết định lấy...', như 「コーヒーにします」 là 'tôi chọn cà phê'. Thứ hai, nó diễn tả việc chủ động làm thay đổi một vật hoặc trạng thái thành trạng thái khác. Với danh từ và tính từ な dùng 「〜にします」, như 「部屋をきれいにします」; với tính từ い đổi 「い」 thành 「く」 rồi thêm 「します」, như 「音を大きくします」. Cần phân biệt với 「〜になる」: 「〜になる」 diễn tả sự thay đổi trạng thái, còn 「〜にする／〜くする」 nhấn mạnh có người chủ động làm cho trạng thái thay đổi.","sourceLesson":44,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-44","sourceRecordId":"grammar-44-4"},{"id":"hn-grammar-45-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「雨が降った場合は、試合を中止します。」","options":["〜てくる","〜場合は","〜るところだ","ちゃんと・きちんと"],"answer":1,"explanation":"〜場合は：Trong trường hợp...; nếu xảy ra trường hợp...; khi... 形：V普通形 + 場合は / Aい普通形 + 場合は / Na + な + 場合は / Nの + 場合は。「〜場合は」 dùng để nêu một tình huống hoặc trường hợp cụ thể rồi nói cách xử lý, kết quả hoặc hành động cần thực hiện khi tình huống đó xảy ra, mang nghĩa 'trong trường hợp..., nếu xảy ra trường hợp...'. Mẫu này thường được dùng trong hướng dẫn, quy định, thông báo hoặc khi nói về những tình huống có thể xảy ra. Với động từ và tính từ い dùng dạng thông thường; với tính từ な dùng 「な場合は」; với danh từ dùng 「Nの場合は」. So với 「〜たら」 hoặc 「〜なら」, 「場合は」 có sắc thái trang trọng và khách quan hơn, đồng thời thường dùng khi xem xét một tình huống như một trường hợp cụ thể.","sourceLesson":45,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-45","sourceRecordId":"grammar-45-1"},{"id":"hn-grammar-45-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「たくさん勉強したのに、試験に合格できませんでした。」","options":["お〜する","〜ないで","〜のに（逆接）","お〜になる"],"answer":2,"explanation":"〜のに（逆接）：Mặc dù...; thế mà...; vậy mà...; dù... nhưng... 形：V普通形 + のに / Aい普通形 + のに / Na + なのに / N + なのに。「〜のに」 dùng để nối hai nội dung trái ngược với điều thường được mong đợi, mang nghĩa 'mặc dù..., vậy mà..., thế mà...'. Vế trước nêu một sự thật hoặc điều kiện mà theo lẽ thường sẽ dẫn đến một kết quả nào đó, nhưng vế sau lại đưa ra kết quả trái với kỳ vọng. Vì vậy, 「のに」 thường chứa sắc thái bất ngờ, thất vọng, tiếc nuối hoặc bất mãn của người nói. Với tính từ な và danh từ ở hiện tại khẳng định dùng 「なのに」. Cần phân biệt với 「〜のに」 ở bài 42 mang nghĩa 'để/dùng cho việc...': 「勉強するのに便利です」 là 'tiện cho việc học', còn 「勉強したのに、分かりません」 là 'mặc dù đã học nhưng vẫn không hiểu'.","sourceLesson":45,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-45","sourceRecordId":"grammar-45-2"},{"id":"hn-grammar-46-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「これから昼ごはんを食べるところです。」","options":["〜ているところだ","〜るところだ","〜にくい","〜てある"],"answer":1,"explanation":"〜るところだ：Sắp...; chuẩn bị...; đang định bắt đầu... 形：V辞書形 + ところです。「V辞書形＋ところです」 dùng để diễn tả một hành động sắp bắt đầu ngay sau thời điểm nói, mang nghĩa 'sắp..., chuẩn bị...'. 「ところ」 trong mẫu này không mang nghĩa địa điểm mà chỉ giai đoạn của hành động. Mẫu thường đi với các phó từ như 「これから」「今から」「ちょうど」 để nhấn mạnh rằng hành động sắp được thực hiện. Cần phân biệt ba mẫu cùng dùng 「ところ」: 「Vるところ」 là ngay trước khi bắt đầu, 「Vているところ」 là đang thực hiện, và 「Vたところ」 là vừa mới hoàn thành.","sourceLesson":46,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-46","sourceRecordId":"grammar-46-1"},{"id":"hn-grammar-46-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「今、昼ごはんを食べているところです。」","options":["〜か〜","〜んです・〜のです","〜ているところだ","Vよう（意向形）"],"answer":2,"explanation":"〜ているところだ：Đang làm... ngay lúc này; đang trong quá trình... 形：Vている + ところです。「Vているところです」 dùng để nhấn mạnh rằng một hành động đang diễn ra đúng tại thời điểm nói, mang nghĩa 'đang làm... ngay lúc này'. So với 「Vています」 chỉ đơn giản diễn tả hành động đang tiếp diễn, 「Vているところです」 tập trung mạnh hơn vào đúng giai đoạn giữa của hành động. Mẫu này thường xuất hiện cùng 「今」「ちょうど」. Vì nhấn mạnh một hành động đang diễn ra, nó thường dùng với các động từ chỉ hành động có điểm bắt đầu và kết thúc tương đối rõ.","sourceLesson":46,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-46","sourceRecordId":"grammar-46-2"},{"id":"hn-grammar-46-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「今、昼ごはんを食べたところです。」","options":["〜そう","〜しか〜ない","〜たところだ","〜とか〜とか"],"answer":2,"explanation":"〜たところだ：Vừa mới làm xong...; vừa mới... 形：Vた + ところです。「Vたところです」 dùng để diễn tả một hành động vừa mới hoàn thành ngay trước thời điểm nói, mang nghĩa 'vừa mới làm xong...'. Khoảng thời gian giữa lúc hành động kết thúc và lúc nói thường rất ngắn. Các từ như 「今」「たった今」「ちょうど」 thường được dùng cùng mẫu này để nhấn mạnh tính vừa mới xảy ra. Cần phân biệt với 「Vたばかり」: 「Vたところ」 nhấn mạnh hành động vừa kết thúc ngay lúc này một cách khách quan, còn 「Vたばかり」 có thể dùng khi người nói cảm thấy sự việc xảy ra chưa lâu, dù thực tế có thể đã qua một khoảng thời gian.","sourceLesson":46,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-46","sourceRecordId":"grammar-46-3"},{"id":"hn-grammar-46-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「私は先月、日本に来たばかりです。」","options":["〜たばかり","〜ておく","Vせる・させる（使役形）","Vていただく"],"answer":0,"explanation":"〜たばかり：Vừa mới...; mới... chưa lâu 形：Vた + ばかりです。「Vたばかりです」 dùng để diễn tả rằng một hành động hoặc sự việc mới xảy ra cách đây không lâu theo cảm nhận của người nói, mang nghĩa 'vừa mới...'. Không giống 「Vたところです」 thường chỉ một hành động vừa kết thúc ngay trước thời điểm nói, khoảng thời gian của 「Vたばかり」 mang tính tương đối và chủ quan. Vì vậy, tùy tình huống, một việc xảy ra vài ngày, vài tháng hoặc thậm chí lâu hơn vẫn có thể dùng 「ばかり」 nếu người nói cảm thấy nó còn mới.","sourceLesson":46,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-46","sourceRecordId":"grammar-46-4"},{"id":"hn-grammar-46-5","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「田中さんは10時に来るはずです。」","options":["〜なくて","〜てしまう・〜ちゃう","では・それでは・じゃあ","〜はずだ"],"answer":3,"explanation":"〜はずだ：Chắc chắn là...; lẽ ra...; theo dự kiến thì...; đáng lẽ phải... 形：V普通形 + はずです / Aい普通形 + はずです / Na + な + はずです / Nの + はずです。「〜はずです」 dùng khi người nói dựa vào thông tin, kế hoạch, kiến thức hoặc lý do hợp lý để đưa ra kết luận có độ chắc chắn cao, mang nghĩa 'chắc là..., theo lý thì..., theo dự kiến thì...'. Đây không chỉ là phỏng đoán cảm tính mà thường có căn cứ. Ví dụ, nếu biết anh Tanaka đã lên kế hoạch đến lúc 10 giờ, có thể nói 「田中さんは10時に来るはずです」. Dạng phủ định 「〜ないはずです」 mang nghĩa 'theo lý thì không...', còn 「〜はずがない」 có nghĩa mạnh hơn là 'không thể nào...'. Cần phân biệt với 「でしょう」: 「でしょう」 là phỏng đoán, còn 「はずです」 thể hiện kỳ vọng hoặc kết luận có căn cứ rõ ràng hơn.","sourceLesson":46,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-46","sourceRecordId":"grammar-46-5"},{"id":"hn-grammar-47-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「天気予報によると、明日は雨が降るそうです。」","options":["〜かどうか","〜すぎる","〜あとで","〜そうだ（伝聞）"],"answer":3,"explanation":"〜そうだ（伝聞）：Nghe nói...; nghe rằng...; người ta nói rằng... 形：V普通形 + そうです / Aい普通形 + そうです / Na + だ + そうです / N + だ + そうです。「〜そうです」 trong bài này dùng để truyền đạt lại thông tin mà người nói nghe hoặc biết được từ người khác, tin tức, báo chí hoặc một nguồn thông tin nào đó, mang nghĩa 'nghe nói rằng..., người ta nói rằng...'. Trước 「そうです」 dùng dạng thông thường. Với tính từ な và danh từ ở hiện tại khẳng định phải giữ 「だ」, như 「元気だそうです」「休みだそうです」. Cần phân biệt với 「〜そうです」 ở bài 43 chỉ vẻ bề ngoài: 「雨が降りそうです」 là 'trông có vẻ sắp mưa', còn 「雨が降るそうです」 là 'nghe nói trời sẽ mưa'.","sourceLesson":47,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-47","sourceRecordId":"grammar-47-1"},{"id":"hn-grammar-47-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「電気が消えています。田中さんは留守のようです。」","options":["〜のに（逆接）","〜ようだ","〜そう","〜たら"],"answer":1,"explanation":"〜ようだ：Có vẻ...; dường như...; hình như... 形：V普通形 + ようです / Aい普通形 + ようです / Na + な + ようです / Nの + ようです。「〜ようです」 dùng khi người nói suy đoán hoặc đưa ra nhận định dựa trên những dấu hiệu, tình hình hoặc thông tin quan sát được, mang nghĩa 'có vẻ..., dường như..., hình như...'. Với tính từ な dùng 「なようです」 và với danh từ dùng 「のようです」. So với 「〜そうです」 chỉ vẻ bề ngoài ở bài 43, 「ようです」 thường là kết luận dựa trên nhiều dấu hiệu hoặc thông tin hơn, không nhất thiết chỉ dựa vào hình thức nhìn thấy trực tiếp. Trong hội thoại, 「〜みたいです」 thường được dùng với nghĩa tương tự nhưng thân mật hơn.","sourceLesson":47,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-47","sourceRecordId":"grammar-47-2"},{"id":"hn-grammar-47-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「隣の部屋から変な音がします。」","options":["〜がする","〜ようにする","〜たら","お〜願う"],"answer":0,"explanation":"〜がする：Có mùi...; có vị...; nghe thấy âm thanh...; có cảm giác... 形：音・声・におい・味・感じ + がします。「〜がします」 dùng để diễn tả những gì người nói cảm nhận được thông qua các giác quan, như âm thanh, giọng nói, mùi, vị hoặc cảm giác. Các cách kết hợp thường gặp gồm 「音がする」 là 'có/nghe thấy âm thanh', 「声がする」 là 'nghe thấy giọng nói', 「においがする」 là 'có mùi', 「味がする」 là 'có vị' và 「感じがする」 là 'có cảm giác'. Mẫu này tập trung vào cảm giác tự nhiên mà người nói nhận được, chứ không phải hành động chủ động nghe, ngửi hoặc nếm.","sourceLesson":47,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-47","sourceRecordId":"grammar-47-3"},{"id":"hn-grammar-47-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「天気予報によると、明日は雨だそうです。」","options":["では・それでは・じゃあ","〜んです・〜のです","〜中","〜によると・〜によれば"],"answer":3,"explanation":"〜によると・〜によれば：Theo...; theo như...; căn cứ theo... 形：N + によると / N + によれば + 情報・伝聞。「〜によると」 và 「〜によれば」 dùng để chỉ nguồn của thông tin mà người nói truyền đạt, mang nghĩa 'theo..., theo như...'. Phía trước thường là nguồn thông tin như 「天気予報」「ニュース」「新聞」「先生の話」. Phía sau thường đi với các mẫu truyền đạt hoặc suy đoán như 「〜そうです」「〜ということです」. 「〜によれば」 có nghĩa gần như giống 「〜によると」 nhưng thường tạo cảm giác hơi trang trọng hơn. Đây là mẫu rất thường được kết hợp với 「〜そうです」 để tạo cấu trúc 'theo X thì nghe nói rằng...'.","sourceLesson":47,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-47","sourceRecordId":"grammar-47-4"},{"id":"hn-grammar-48-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「母は子どもに野菜を食べさせます。」","options":["それに","Vせる・させる（使役形）","〜あとで","〜ようになる"],"answer":1,"explanation":"Vせる・させる（使役形）：Bắt/khiến ai làm...; cho phép/để ai làm... 形：五段動詞: う段→あ段 + せる / 一段動詞: る→させる / する→させる / 来る→来させる。「使役形」 là thể sai khiến, dùng khi một người khiến, yêu cầu, bắt hoặc cho phép một người khác thực hiện hành động. Tùy quan hệ giữa hai người và ngữ cảnh, nó có thể mang nghĩa 'bắt/khiến ai làm...' hoặc 'cho phép/để ai làm...'. Với động từ nhóm I, đổi âm cuối từ hàng う sang hàng あ rồi thêm 「せる」, như 「行く→行かせる」「読む→読ませる」; riêng động từ kết thúc bằng 「う」 đổi thành 「わせる」, như 「買う→買わせる」. Với động từ nhóm II, bỏ 「る」 rồi thêm 「させる」, như 「食べる→食べさせる」. 「する」 thành 「させる」 và 「来る」 thành 「来させる」. Với tự động từ, người thực hiện hành động thường được đánh dấu bằng 「を」, như 「子どもを公園で遊ばせます」. Với tha động từ, người thực hiện thường được đánh dấu bằng 「に」 và đối tượng của hành động vẫn dùng 「を」, như 「子どもに野菜を食べさせます」. Trong mẫu xin phép 「Vさせてください」, người nói yêu cầu người nghe cho phép mình làm một việc, mang nghĩa 'xin hãy cho phép tôi...'.","sourceLesson":48,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-48","sourceRecordId":"grammar-48-1"},{"id":"hn-grammar-49-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「先生はこの本をお読みになりました。」","options":["お〜になる","〜ばいい","V辞書形 + な","それに"],"answer":0,"explanation":"お〜になる：Làm... (kính ngữ); cách nói tôn kính hành động của người khác 形：お + Vます語幹 + になります / ご + 漢語系Vます語幹 + になります。「お〜になります」 là một mẫu kính ngữ thuộc 「尊敬語」, dùng để nâng hành động của người được nói đến, chẳng hạn khách hàng, giáo viên, cấp trên hoặc người lớn tuổi. Cách tạo cơ bản là lấy động từ thể ます, bỏ 「ます」 rồi đặt vào 「お〜になります」, như 「読みます→お読みになります」「帰ります→お帰りになります」. Với một số động từ gốc Hán có 「します」, có thể dùng 「ご〜になります」 như 「利用します→ご利用になります」. Tuy nhiên, không phải động từ nào cũng dùng được mẫu này. Những động từ đã có dạng kính ngữ đặc biệt như 「行く・来る・いる→いらっしゃる」「見る→ご覧になる」「食べる・飲む→召し上がる」 thường ưu tiên dùng dạng đặc biệt. Ngoài ra, các động từ có thân ます chỉ gồm một âm như 「見ます」「寝ます」 thường không dùng dạng 「お〜になります」.","sourceLesson":49,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-49","sourceRecordId":"grammar-49-1"},{"id":"hn-grammar-49-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「先生は今、研究室にいらっしゃいます。」","options":["〜てある","いらっしゃる","〜しか〜ない","Vて、〜（原因・理由）"],"answer":1,"explanation":"いらっしゃる：Ở; có mặt; đi; đến (kính ngữ) 形：いる・行く・来る → いらっしゃいます。「いらっしゃる」 là động từ kính ngữ đặc biệt của ba động từ 「いる」「行く」「来る」. Nó được dùng để nâng người thực hiện hành động, mang nghĩa 'ở/có mặt', 'đi' hoặc 'đến' tùy theo ngữ cảnh. Dạng lịch sự thường dùng là 「いらっしゃいます」, không phải 「いらっしゃります」. Vì một từ có thể tương ứng với ba động từ khác nhau nên cần dựa vào trợ từ và ngữ cảnh để xác định nghĩa. Ví dụ 「会社にいらっしゃいます」 thường là 'đang ở công ty', 「東京へいらっしゃいます」 có thể là 'đi/đến Tokyo'. Cụm 「いらっしゃいませ」 thường được nhân viên cửa hàng hoặc nhà hàng dùng để chào đón khách.","sourceLesson":49,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-49","sourceRecordId":"grammar-49-2"},{"id":"hn-grammar-49-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「こちらで少しお待ちください。」","options":["お〜ください","〜中","〜なくて","〜でできる・〜からできる"],"answer":0,"explanation":"お〜ください：Xin vui lòng...; kính mời... (cách yêu cầu kính trọng) 形：お + Vます語幹 + ください / ご + 漢語系Vます語幹 + ください。「お〜ください」 là mẫu kính ngữ dùng để yêu cầu, mời hoặc hướng dẫn người nghe thực hiện một hành động một cách tôn kính, mang nghĩa 'xin vui lòng..., kính mời...'. Cách tạo cơ bản là lấy động từ thể ます, bỏ 「ます」 rồi thêm 「お〜ください」, như 「待ちます→お待ちください」「入りください→お入りください」. Với nhiều từ Hán kết hợp với 「する」, thường dùng 「ご〜ください」, như 「注意する→ご注意ください」「利用する→ご利用ください」. Mẫu này trang trọng và kính trọng hơn 「〜てください」, vì vậy rất thường gặp trong dịch vụ khách hàng, thông báo và hướng dẫn. Một số động từ có cách nói kính ngữ đặc biệt nên không áp dụng máy móc mẫu này.","sourceLesson":49,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-49","sourceRecordId":"grammar-49-3"},{"id":"hn-grammar-50-1","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「荷物をお持ちします。」","options":["〜ばいい","まだ","お〜する","では・それでは・じゃあ"],"answer":2,"explanation":"お〜する：Tôi xin làm...; tôi sẽ làm... (khiêm nhường ngữ) 形：お + Vます語幹 + します / ご + 漢語系Vます語幹 + します。「お〜します」 là mẫu 「謙譲語」 dùng để hạ thấp hành động của bản thân hoặc người thuộc phía mình, qua đó thể hiện sự kính trọng đối với người mà hành động đó hướng đến. Cách tạo cơ bản là lấy động từ thể ます, bỏ 「ます」 rồi đặt vào 「お〜します」, như 「持ちます→お持ちします」「送ります→お送りします」. Với nhiều động từ gốc Hán kết hợp với 「します」, thường dùng 「ご〜します」, như 「説明します→ご説明します」「案内します→ご案内します」. Mẫu này thường dùng khi hành động của người nói có liên quan hoặc mang lợi ích đến người cần được kính trọng. Không dùng mẫu này để nâng hành động của đối phương; trường hợp đó dùng 「尊敬語」.","sourceLesson":50,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-50","sourceRecordId":"grammar-50-1"},{"id":"hn-grammar-50-2","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「詳しいことは後でご説明いたします。」","options":["数量詞 + も","〜のが上手","〜たばかり","いたす"],"answer":3,"explanation":"いたす：Làm (khiêm nhường ngữ của する); xin làm... 形：する → いたします / N + いたします。「いたす」 là khiêm nhường ngữ của 「する」, dùng để hạ thấp hành động của người nói hoặc phía người nói nhằm thể hiện sự kính trọng đối với đối phương. Trong giao tiếp lịch sự, dạng 「いたします」 được sử dụng rất phổ biến. Nó thường xuất hiện trong các cách nói như 「お願いします→お願いいたします」「連絡します→連絡いたします」「説明します→説明いたします」. So với 「します」, 「いたします」 trang trọng và khiêm nhường hơn, vì vậy thường gặp trong môi trường công việc, dịch vụ khách hàng và giao tiếp với cấp trên hoặc khách hàng.","sourceLesson":50,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-50","sourceRecordId":"grammar-50-2"},{"id":"hn-grammar-50-3","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「こちらで少々お待ち願います。」","options":["いたす","Vていただく","〜か〜","お〜願う"],"answer":3,"explanation":"お〜願う：Xin vui lòng...; kính nhờ...; có thể vui lòng... được không? 形：お + Vます語幹 + 願います / ご + N + 願います。「お〜願います」 là cách yêu cầu hoặc nhờ vả lịch sự và trang trọng, thường được dùng trong môi trường công việc, dịch vụ, thông báo hoặc khi nói với người cần thể hiện sự kính trọng. Cấu trúc thường gặp là 「お＋Vます語幹＋願います」, như 「待つ→お待ち願います」. Với một số danh từ gốc Hán có thể dùng 「ご〜願います」. So với 「〜てください」, mẫu này mang tính trang trọng và thường xuất hiện trong lời hướng dẫn hoặc yêu cầu chính thức. Dạng 「お願いいたします」 còn lịch sự và khiêm nhường hơn, được sử dụng rất phổ biến trong giao tiếp thương mại.","sourceLesson":50,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-50","sourceRecordId":"grammar-50-3"},{"id":"hn-grammar-50-4","section":"grammar","type":"文法・用法","prompt":"文中で使われている文法を選んでください。\n「それでは、会議を始めます。」","options":["〜ようだ","〜すぎる","〜にくい","では・それでは・じゃあ"],"answer":3,"explanation":"では・それでは・じゃあ：Vậy thì...; nếu vậy...; thế thì...; được rồi... 形：では / それでは / じゃあ + 文。「では」「それでは」「じゃあ」 là các liên từ dùng để chuyển sang hành động, kết luận hoặc chủ đề tiếp theo dựa trên tình huống vừa được nói đến, mang nghĩa 'vậy thì, nếu vậy, thế thì'. 「それでは」 là dạng đầy đủ và tương đối lịch sự, thường dùng trong các tình huống trang trọng hoặc khi chuyển sang bước tiếp theo. 「では」 ngắn hơn nhưng vẫn có thể dùng trong giao tiếp lịch sự. 「じゃあ」 là dạng hội thoại thân mật của 「では」, thường dùng với bạn bè, gia đình hoặc người thân quen. Các từ này cũng thường được dùng khi kết thúc cuộc trò chuyện, như 「それでは、失礼いたします」.","sourceLesson":50,"sourceUrl":"https://han-nichi.vercel.app/grammar/minna-2-n4/lesson-50","sourceRecordId":"grammar-50-4"}];
